// ---- ステージの結果 ----
// 倒しきった後の結果の画面。見出しを出してから、記録を 1 行ずつ数え上げる。最後に合計を数え上げて叩きつけ、右へ巨大なランクを落として画面を揺らす。
// 一時停止中に出すので、時間は実時間（performance.now）で進め、音は UI の AudioContext で鳴らす。
// 途中で決定を押すと、残りを飛ばして最後の形にする。
// 出しきって MASTERY_WAIT 秒たったら、左の記録と合計を武器の熟練度に入れ替え、稼いだ XP でゲージを伸ばす（ここは飛ばさない）。
// 同時に、右のランクの枠をいちばん良かったキルの映像に入れ替える
// 初めて達成した実績があれば、合計の下にそのバッジを並べる（熟練度に入れ替えても残す）
import * as sfx from './audio.js';
import { masteryOf } from './mastery.js';
import { TIER_NAMES, type Feat } from './challenges.js';
import { badgePlate } from './ui/cardHonors.js';

export interface ResultData {
  stageNo: string;
  stageName: string;
  difficulty: string;
  time: number;
  kills: number;
  rankScale: number; // ランクのしきい値に掛ける数（ふつうは倒した数。ボスはボス専用の値）
  damage: number;
  headshotRate: number | null; // ハンドガンと弓で当てたうち頭に当たった割合（0〜1）。撃って当てていなければ null で、行を出さない
  score: number;
  newTime: boolean;
  newScore: boolean;
  mastery?: { name: string; ja: string; before: number; gained: number }; // 持ち込んだ武器の XP（このステージの前と、稼いだ分）
  // cleared: ランクまで届いて達成したか（届かなければ need に求めたランクを入れる）。reward: 初めての達成で解放したスキンの名前
  // bonus: この達成で解放した見出しの追加のご褒美（フレーム）の名前
  mission?: { name: string; ja: string; cleared: boolean; rank: string; need: string; first: boolean; newTime: boolean; reward?: string; bonus?: string };
  feats: Feat[]; // このプレイで初めて達成した実績。札を押した後に、もらえるバッジを 1 つずつ出す
  clip?: { aspect: number; play: (canvas: HTMLCanvasElement) => void }; // 録れたハイライト（fx/replayClip.ts）。熟練度に入れ替えるとき、ランクの枠を映像に入れ替える
}

export function fmtTime(t: number) {
  const cs = Math.floor(t * 100);
  return `${Math.floor(cs / 6000)}:${String(Math.floor(cs / 100) % 60).padStart(2, '0')}.${String(cs % 100).padStart(2, '0')}`;
}
const fmtInt = (n: number) => Math.round(n).toLocaleString('en-US');

// 最終スコア: 倒して稼いだ点数に、速く倒しきるほど大きい倍率を掛ける。受けたダメージは関係させない
// 時間の倍率は開始時がいちばん高く、時間とともに下がって、基準タイム par（ふつうは倒した数から決める）で ×1.0 になる。
// それより遅くても ×1.0 のまま（下回らない）。基準タイムは画面には出さない
const PAR_PER_KILL = 10; // 1 体あたりの基準秒数
export const killPar = (kills: number) => PAR_PER_KILL * Math.max(1, kills);
const TIME_MAX = 3; // 開始時の倍率
function timeMultiplier(time: number, par: number, maxMultiplier = TIME_MAX) {
  const r = Math.min(1, time / par); // 基準タイムとの比
  return maxMultiplier - (maxMultiplier - 1) * r;
}
export function finalScore(killScore: number, time: number, par: number, maxMultiplier = TIME_MAX) {
  return Math.round(killScore * timeMultiplier(time, par, maxMultiplier));
}

// ランク: 最終スコアだけで決める。ステージごとに敵の数が違うので、しきい値は「1 体あたりの点数 × 倒した数」（目安。遊びながら詰める）
// 時間の倍率が乗るので、1 体 5 秒ペース（×2.0）を中心に据えている。SS は S の上に置いた、詰めきった人向けの段。
// SSS はほぼ届かない段: 毎回加点を +4 前後積み（500 点）、しかも 1 体 2 秒を切るペース（×2.6 以上）でやっと届く
const RANKS = [
  ['SSS', 1400, 'IMPOSSIBLE'],
  ['SS', 800, 'ULTIMATE'],
  ['S', 600, 'SUPERB'],
  ['A', 420, 'GREAT'],
  ['B', 260, 'GOOD'],
  ['C', 0, 'CLEAR'],
] as const;
// ヘッドショット率が 9 割を超えたら、スコアによらずこの段にする（冗談のランク）
const CHEATER_RANK = ['Cheater?', 0, 'TOO ACCURATE'] as const;
const CHEATER_HEADSHOT_RATE = 0.9;
// スコアだけで決めたランクの文字（ミッションの判定にも使う。冗談のランクは入れない）
export const scoreRank = (score: number, rankScale: number) => RANKS.find(([, per]) => score >= per * rankScale)![0];
function rankOf(d: ResultData) {
  if (d.headshotRate !== null && d.headshotRate > CHEATER_HEADSHOT_RATE) return CHEATER_RANK;
  return RANKS.find(([, per]) => d.score >= per * d.rankScale)!;
}

// 出す順番（秒）
const T_HEAD = 0.1; // 見出し
const T_ROW = 0.55; // 1 行目
const ROW_GAP = 0.62;
const ROW_COUNT = 0.5; // 1 行を数え上げる時間
const SCORE_COUNT = 1.3;
const FEAT_GAP = 0.32; // 実績のバッジを 1 つずつ出す間隔
// 合計から後は、出す行の数（ヘッドショット率の行があるか）でずらす。実績があれば、その数だけメニューを遅らせる
const timesAfterRows = (n: number, feats: number) => {
  const score = T_ROW + ROW_GAP * n + 0.1;
  const slam = score + 0.2 + SCORE_COUNT + 0.18; // 数え終えてから一拍おいて確定
  const rank = slam + 0.7;
  const tags = rank + 0.55;
  const feat = tags + 0.6;
  return { score, slam, rank, tags, feat, menu: feats ? feat + 0.25 + FEAT_GAP * feats : tags + 0.45 };
};
const TICK_GAP = 0.045; // 数え上げの刻みの間隔
const MASTERY_WAIT = 3; // 出しきってから熟練度に入れ替えるまで
const MASTERY_COUNT = 1.6; // XP を数え上げてゲージを伸ばす時間（入れ替えが出きってから）

const view = document.querySelector<HTMLElement>('#overlay .result-view')!;
const q = <T extends HTMLElement = HTMLElement>(sel: string) => view.querySelector<T>(sel)!;
const shake = q('.rv-shake');
const flash = q('.rv-flash');
const ghost = q('.rv-ghost');
const kicker = q('.rv-kicker');
const title = q('.rv-title');
const rule = q('.rv-rule');
const rows = {
  time: q('[data-row="time"]'),
  damage: q('[data-row="damage"]'),
  headshot: q('[data-row="headshot"]'),
  best: q('[data-row="best"]'),
  falls: q('[data-row="falls"]'),
};
const score = q('.rv-score');
const scoreLabel = score.querySelector<HTMLElement>('small')!;
const SCORE_LABEL = scoreLabel.innerHTML;
const scoreVal = score.querySelector<HTMLElement>('b')!;
const meter = q('.rv-meter');
const meterFill = meter.querySelector<HTMLElement>('.fill')!;
// メーターの右端は SSS の地点（遠さがそのまま見えるようにする）。目印の位置は 1 体あたりのしきい値の比なので、倒した数によらず同じ
const METER_MAX = RANKS[0][1];
let marks: { mk: HTMLElement; at: number }[] = [];
// 目印を置き直す（at はメーターの左端からの割合）。パルクールではメダルの目印にする
function setMarks(list: { label: string; at: number }[]) {
  for (const m of marks) m.mk.remove();
  marks = list.map(({ label, at }) => {
    const mk = document.createElement('i');
    mk.className = 'mk';
    mk.style.setProperty('--x', `${at * 100}%`);
    mk.innerHTML = `<span>${label}</span>`;
    meter.append(mk);
    return { mk, at };
  });
}
const RANK_MARKS = RANKS.map(([letter, per]) => ({ label: letter, at: per / METER_MAX }));
setMarks(RANK_MARKS);
// メーターを p（0〜1）まで伸ばし、届いた目印を点ける
function setMeter(p: number) {
  meterFill.style.setProperty('--p', String(p));
  for (const m of marks) if (p >= m.at && !m.mk.classList.contains('on')) m.mk.classList.add('on');
}
const rank = q('.rv-rank');
const rankLabel = rank.querySelector<HTMLElement>('small')!;
const RANK_LABEL = rankLabel.innerHTML;
const rankLetter = q('.rv-letter');
const rankNote = q('.rv-rank-note');
const clipCanvas = q<HTMLCanvasElement>('.rv-clip');
const menu = q('.rv-menu');
const main = q('.rv-main');
const rowsBox = q('.rv-rows');
const mastery = q('.rv-mastery');
const wait = q('.rv-wait');
wait.style.setProperty('--wait', `${MASTERY_WAIT}s`);
const msName = q('.rv-ms-name');
const msJa = q('.rv-ms-ja');
const msLevel = q('.rv-ms-lv b');
const msUp = q('.rv-ms-up');
const msBar = q('.rv-ms-bar');
const msGain = q('.rv-ms-gain');
const msNext = q('.rv-ms-next');
const featsBox = q('.rv-feats');
const featList = q('.rv-feat-list');
// 熟練度の表示を XP の量に合わせる。上がったレベルを返す
function setMastery(xp: number, gained: number) {
  const m = masteryOf(xp);
  msLevel.textContent = String(m.level);
  msBar.style.setProperty('--xp', String(m.into / m.need));
  msGain.textContent = `+${fmtInt(gained)} XP`;
  msNext.textContent = `${fmtInt(m.into)} / ${fmtInt(m.need)}`;
  return m.level;
}
const tags = {
  time: q('[data-tag="time"]'),
  damage: q('[data-tag="damage"]'),
  score: q('[data-tag="score"]'),
  falls: q('[data-tag="falls"]'),
};

interface Count {
  start: number;
  dur: number;
  set: (k: number) => void; // k は 0〜1
  done: () => void;
  lastTick: number;
  silent?: boolean; // 刻みの音を鳴らさない
}
let steps: { at: number; run: () => void }[] = [];
let counts: Count[] = [];
let t0 = 0;
let running = false; // 決定で飛ばせる間（メニューを出すまで）
let menuAt = 0; // メニューを出す時刻。飛ばしたらここまで進める
let loop = 0; // 出し直したら前の回の毎フレームを止める
let quiet = false; // 飛ばしている間は、途中の音を鳴らさない
let onDone: (() => void) | null = null;

// クラスを外して付け直し、CSS のアニメーションを最初からやり直す
function restart(node: HTMLElement, cls: string) {
  node.classList.remove(cls);
  void node.offsetWidth;
  node.classList.add(cls);
}
const show = (node: HTMLElement) => restart(node, 'show');
const play = (fn: () => void) => {
  if (!quiet) fn();
};
// 画面全体を一瞬揺らす（強さは px）
function shakeView(p: number) {
  if (quiet) return;
  shake.animate(
    [
      { transform: `translate(${p}px, ${-p * 0.6}px)` },
      { transform: `translate(${-p * 0.8}px, ${p * 0.5}px)` },
      { transform: `translate(${p * 0.5}px, ${p * 0.3}px)` },
      { transform: `translate(${-p * 0.25}px, ${-p * 0.2}px)` },
      { transform: 'none' },
    ],
    { duration: 380, easing: 'ease-out' },
  );
}

// 値を 0 から数え上げる。進みは終わりほどゆっくりにする
function countUp(at: number, dur: number, el: HTMLElement, to: number, fmt: (v: number) => string, after?: () => void) {
  steps.push({
    at,
    run: () => {
      counts.push({
        start: at,
        dur,
        lastTick: -1,
        set: (k) => (el.textContent = fmt(to * (1 - (1 - k) ** 3))),
        done: () => {
          el.textContent = fmt(to);
          restart(el, 'lock');
          after?.();
        },
      });
    },
  });
}

function addRow(at: number, row: HTMLElement, to: number, fmt: (v: number) => string) {
  const val = row.querySelector<HTMLElement>('b')!;
  val.textContent = fmt(0);
  steps.push({ at, run: () => show(row) });
  countUp(at + 0.12, ROW_COUNT, val, to, fmt, () => play(sfx.playResultLock));
}

// 出し直す前に、前の回の演出の跡を消す。parkour ならパルクールの並び（行・見出し・目印）に組み替える
function resetView(parkour: boolean) {
  steps = [];
  counts = [];
  quiet = false;
  for (const node of view.querySelectorAll('.show, .lock, .on, .slam, .swapped, .clip')) node.classList.remove('show', 'lock', 'on', 'slam', 'swapped', 'clip');
  view.classList.toggle('parkour', parkour);
  rows.time.hidden = rows.damage.hidden = parkour;
  rows.best.hidden = rows.falls.hidden = !parkour;
  rows.headshot.hidden = true;
  featsBox.hidden = true;
  scoreLabel.innerHTML = parkour ? 'TIME<span class="jp">タイム</span>' : SCORE_LABEL;
  rankLabel.innerHTML = parkour ? 'MEDAL<span class="jp">メダル</span>' : RANK_LABEL;
  title.querySelector('.s1')!.textContent = parkour ? 'COURSE' : 'STAGE';
  tags.score.textContent = 'NEW RECORD';
  setMarks(parkour ? [] : RANK_MARKS);
}

export function showResult(d: ResultData, done?: () => void) {
  resetView(false);
  onDone = done ?? null;
  const [letter, , note] = rankOf(d);

  kicker.textContent = `STAGE ${d.stageNo} — ${d.stageName} / ${d.difficulty}`;
  ghost.textContent = `${d.stageName} ${d.stageName} `;
  rankLetter.textContent = letter;
  rankLetter.dataset.rank = letter;
  rankNote.textContent = note;
  scoreVal.textContent = '0';
  setMeter(0);
  const meterTo = Math.min(1, d.score / (METER_MAX * Math.max(1, d.rankScale)));

  steps.push({
    at: T_HEAD,
    run: () => {
      show(ghost);
      show(kicker);
      show(title);
      show(rule);
      play(sfx.playUiOpen);
    },
  });
  addRow(T_ROW, rows.time, d.time, fmtTime);
  addRow(T_ROW + ROW_GAP, rows.damage, d.damage, (v) => String(Math.round(v)));
  rows.headshot.hidden = d.headshotRate === null;
  if (d.headshotRate !== null) addRow(T_ROW + ROW_GAP * 2, rows.headshot, d.headshotRate * 100, (v) => `${Math.round(v)}%`);
  const T = timesAfterRows(d.headshotRate === null ? 2 : 3, d.feats.length);
  steps.push({ at: T.score, run: () => show(score) });
  steps.push({
    at: T.score + 0.2,
    run: () => {
      counts.push({
        start: T.score + 0.2,
        dur: SCORE_COUNT,
        lastTick: -1,
        set: (k) => {
          const e = 1 - (1 - k) ** 3;
          scoreVal.textContent = fmtInt(d.score * e);
          setMeter(meterTo * e);
        },
        done: () => {
          scoreVal.textContent = fmtInt(d.score);
          setMeter(meterTo);
        },
      });
    },
  });
  steps.push({
    at: T.slam,
    run: () => {
      score.classList.add('slam');
      restart(scoreVal, 'lock');
      play(sfx.playResultScore);
      shakeView(6);
    },
  });
  steps.push({
    at: T.rank,
    run: () => {
      show(rank);
      // 文字が落ちきる瞬間に合わせて鳴らし、揺らす
      setTimeout(() => {
        sfx.playResultRank(letter);
        shakeView(letter === 'SSS' ? 34 : letter === 'SS' ? 24 : letter === 'S' ? 18 : 12);
        restart(flash, 'on');
      }, quiet ? 0 : 180);
    },
  });
  const tagList: HTMLElement[] = [];
  if (d.newTime) tagList.push(tags.time);
  if (d.damage <= 0) tagList.push(tags.damage);
  if (d.newScore) tagList.push(tags.score);
  tagList.forEach((tag, i) =>
    steps.push({
      at: T.tags + i * 0.16,
      run: () => {
        show(tag);
        play(sfx.playResultStamp);
      },
    }),
  );
  featsBox.hidden = !d.feats.length;
  featList.innerHTML = d.feats
    .map((f) => `<div class="rv-feat">${badgePlate(f)}<b>${f.name}<small>${f.ja}<i>${TIER_NAMES[f.tier - 1]}</i></small></b></div>`)
    .join('');
  if (d.feats.length) {
    steps.push({ at: T.feat, run: () => show(featsBox) });
    [...featList.children].forEach((node, i) =>
      steps.push({
        at: T.feat + 0.25 + i * FEAT_GAP,
        run: () => {
          show(node as HTMLElement);
          play(sfx.playResultStamp);
        },
      }),
    );
  }
  steps.push({
    at: T.menu,
    run: () => {
      show(menu);
      running = false;
      onDone?.();
    },
  });
  menuAt = T.menu;
  if (d.mastery) addMastery(d.mastery, T.menu + MASTERY_WAIT);
  if (d.mission) {
    const m = d.mission;
    steps.push({ at: T.menu, run: () => show(wait) });
    steps.push({ at: T.menu + MASTERY_WAIT, run: () => {
      main.classList.add('swapped');
      mastery.style.top = `${rowsBox.offsetTop}px`;
      mastery.replaceChildren();
      // 熟練度と同じ置き方で、ミッションの名前と、初めての達成か最短を縮めたかの札。
      // ランクが足りなければ失敗にして、取ったランクと求めたランクを出す。初めての達成ならご褒美の札も足す
      const head = `<div class="rv-ms-head"><span class="rv-ms-name">${m.name}</span><span class="rv-ms-ja">${m.ja}</span></div>`;
      if (!m.cleared) mastery.innerHTML = `<small>MISSION FAILED</small>${head}<em class="rv-mi-tag">RANK ${m.rank} — NEED ${m.need}</em>`;
      else {
        const tag = m.first ? 'FIRST CLEAR' : m.newTime ? 'NEW BEST TIME' : 'CLEARED';
        const reward = (m.reward ? ` <em class="rv-mi-tag new">${m.reward} UNLOCKED</em>` : '') + (m.bonus ? ` <em class="rv-mi-tag new">${m.bonus} UNLOCKED</em>` : '');
        mastery.innerHTML = `<small>MISSION CLEAR</small>${head}<em class="rv-mi-tag${m.first || m.newTime ? ' new' : ''}">${tag}</em>${reward}`;
      }
      show(mastery);
    } });
  }
  const clip = d.clip;
  if (clip) {
    clipCanvas.style.aspectRatio = String(clip.aspect);
    steps.push({
      at: T.menu + MASTERY_WAIT,
      run: () => {
        rank.classList.add('clip');
        clip.play(clipCanvas);
      },
    });
  }
  steps.sort((a, b) => a.at - b.at);

  document.body.classList.add('result-shown');
  running = true;
  t0 = performance.now();
  const id = ++loop;
  requestAnimationFrame((now) => frame(now, id));
}

// ---- パルクールの結果 ----
// 同じ画面を組み替えて使う。左に前回までの自己ベストと落ちた回数、合計の場所にタイムを数え上げ、
// メーターにはメダルの目印を並べる（速いほど右へ伸びる）。右の大きな文字は取ったメダル
export interface ParkourResultData {
  name: string;
  time: number;
  best: number | null; // この回より前の自己ベスト。初めてなら null
  falls: number;
  newTime: boolean;
  first: boolean;
  gold: number;
  silver: number;
  bronze: number;
}
const MEDALS = [
  ['GOLD', 'gold'],
  ['SILVER', 'silver'],
  ['BRONZE', 'bronze'],
] as const;
// メーター: ブロンズの 1.3 倍の時間で 0、ゴールドの 0.8 倍で振り切る
const medalMeter = (d: ParkourResultData, t: number) => {
  const slow = d.bronze * 1.3;
  const fast = d.gold * 0.8;
  return Math.min(1, Math.max(0, (slow - t) / (slow - fast)));
};
export function showParkourResult(d: ParkourResultData, done?: () => void) {
  resetView(true);
  onDone = done ?? null;
  setMarks(MEDALS.map(([label, key]) => ({ label, at: medalMeter(d, d[key]) })));
  const meterTo = medalMeter(d, d.time);
  const got = MEDALS.find(([, key]) => d.time <= d[key]);
  const letter = got ? got[0] : 'FINISH';
  // 次のメダルまでのタイムを下に添える
  const next = [...MEDALS].reverse().find(([, key]) => d.time > d[key]);
  const nextNote = !next ? 'TOP MEDAL' : `NEXT ${next[0]} ${fmtTime(d[next[1]])}`;

  kicker.textContent = `PARKOUR — ${d.name}`;
  ghost.textContent = 'PARKOUR PARKOUR ';
  rankLetter.textContent = letter;
  rankLetter.dataset.rank = letter;
  rankNote.textContent = nextNote;
  scoreVal.textContent = fmtTime(0);
  setMeter(0);

  steps.push({
    at: T_HEAD,
    run: () => {
      show(ghost);
      show(kicker);
      show(title);
      show(rule);
      play(sfx.playUiOpen);
    },
  });
  // 前回までの自己ベストは数え上げずに出す（無ければ線）
  rows.best.querySelector<HTMLElement>('b')!.textContent = d.best === null ? '—' : fmtTime(d.best);
  steps.push({
    at: T_ROW,
    run: () => {
      show(rows.best);
      play(sfx.playResultLock);
    },
  });
  addRow(T_ROW + ROW_GAP, rows.falls, d.falls, (v) => String(Math.round(v)));
  const T = timesAfterRows(2, 0);
  steps.push({ at: T.score, run: () => show(score) });
  steps.push({
    at: T.score + 0.2,
    run: () => {
      counts.push({
        start: T.score + 0.2,
        dur: SCORE_COUNT,
        lastTick: -1,
        set: (k) => {
          const e = 1 - (1 - k) ** 3;
          scoreVal.textContent = fmtTime(d.time * e);
          setMeter(meterTo * e);
        },
        done: () => {
          scoreVal.textContent = fmtTime(d.time);
          setMeter(meterTo);
        },
      });
    },
  });
  steps.push({
    at: T.slam,
    run: () => {
      score.classList.add('slam');
      restart(scoreVal, 'lock');
      play(sfx.playResultScore);
      shakeView(6);
    },
  });
  // メダルの重さで鳴らし分ける（ランクの音を借りる）
  const sound = got?.[0] === 'GOLD' ? 'SS' : got?.[0] === 'SILVER' ? 'S' : got ? 'A' : 'C';
  steps.push({
    at: T.rank,
    run: () => {
      show(rank);
      setTimeout(() => {
        sfx.playResultRank(sound);
        shakeView(got?.[0] === 'GOLD' ? 24 : got ? 16 : 10);
        restart(flash, 'on');
      }, quiet ? 0 : 180);
    },
  });
  tags.score.textContent = d.first ? 'FIRST CLEAR' : 'NEW RECORD';
  const tagList: HTMLElement[] = [];
  if (d.newTime) tagList.push(tags.score);
  if (d.falls === 0) tagList.push(tags.falls);
  tagList.forEach((tag, i) =>
    steps.push({
      at: T.tags + i * 0.16,
      run: () => {
        show(tag);
        play(sfx.playResultStamp);
      },
    }),
  );
  steps.push({
    at: T.menu,
    run: () => {
      show(menu);
      running = false;
      onDone?.();
    },
  });
  menuAt = T.menu;
  steps.sort((a, b) => a.at - b.at);

  document.body.classList.add('result-shown');
  running = true;
  t0 = performance.now();
  const id = ++loop;
  requestAnimationFrame((now) => frame(now, id));
}

// 記録と合計を引っ込めて熟練度を出し、XP を数え上げる。レベルが上がったら数字を締めて LEVEL UP を添え、小さく鳴らす
function addMastery(ms: NonNullable<ResultData['mastery']>, at: number) {
  steps.push({ at: at - MASTERY_WAIT, run: () => show(wait) }); // メニューと一緒に、入れ替わるまでの残りを伸ばし始める
  msName.textContent = ms.name;
  msJa.textContent = ms.ja;
  let level = setMastery(ms.before, 0);
  steps.push({
    at,
    run: () => {
      main.classList.add('swapped');
      mastery.style.top = `${rowsBox.offsetTop}px`;
      show(mastery);
    },
  });
  steps.push({
    at: at + 0.5,
    run: () => {
      counts.push({
        start: at + 0.5,
        dur: MASTERY_COUNT,
        lastTick: -1,
        silent: true,
        set: (k) => {
          const e = 1 - (1 - k) ** 3;
          const now = setMastery(ms.before + ms.gained * e, ms.gained * e);
          if (now > level) {
            level = now;
            restart(msLevel, 'lock');
            show(msUp);
            sfx.playResultLock();
          }
        },
        done: () => {
          if (setMastery(ms.before + ms.gained, ms.gained) > level) {
            restart(msLevel, 'lock');
            show(msUp);
            sfx.playResultLock();
          }
        },
      });
    },
  });
}

function advance(t: number) {
  while (steps.length && steps[0].at <= t) steps.shift()!.run();
  counts = counts.filter((c) => {
    const k = Math.min(1, (t - c.start) / c.dur);
    if (k >= 1) {
      c.done();
      return false;
    }
    c.set(Math.max(0, k));
    if (!quiet && !c.silent && t - c.lastTick >= TICK_GAP) {
      c.lastTick = t;
      sfx.playResultTick(k);
    }
    return true;
  });
}

// メニューを出した後も、熟練度の入れ替えが終わるまでは進める。タイトルへ戻って画面が消えたらやめる
function frame(now: number, id: number) {
  if (id !== loop || !view.offsetParent) return;
  advance((now - t0) / 1000);
  if (steps.length || counts.length) requestAnimationFrame((n) => frame(n, id));
}

// 演出の途中ならメニューまで飛ばして true を返す。もう終わっていれば false（呼んだ側でタイトルへ戻す）
export function skipResult(): boolean {
  if (!running) return false;
  // メニューを出すところまで飛ばし、熟練度の入れ替えはそこから MASTERY_WAIT 秒後に回す
  quiet = true;
  advance(menuAt);
  quiet = false;
  t0 = performance.now() - menuAt * 1000;
  return true;
}
