// ---- 効果音 ----
// sfx/ の録音素材（CC0。出どころは sfx/CREDITS.md）と WebAudio の合成音を重ねて鳴らす。
// 素材は同じ種類から毎回違うものを選び、高さ・音量・左右を少しずつ揺らして、連打しても同じ音に聞こえないようにする。
// 全体は 1 本のバスにまとめ、部屋の残響を足してから、スロー用のこもり → コンプレッサーを通して出す

let ctx: AudioContext | null = null;
let noiseBuffer: AudioBuffer;
// 最低画質の音: 残響を切り、重なる音を減らす（残響の計算と、音ごとの部品作りが弱い CPU では重い）
let liteAudio = false;
let reverbConv: ConvolverNode | null = null;
let hallConvNode: ConvolverNode | null = null;
export function setLiteAudio(on: boolean) {
  if (on === liteAudio) return;
  liteAudio = on;
  routeReverb();
}
function routeReverb() {
  if (!reverbConv || !hallConvNode) return;
  if (liteAudio) {
    reverbIn.disconnect();
    hallIn.disconnect();
  } else {
    reverbIn.connect(reverbConv);
    hallIn.connect(hallConvNode);
  }
}
let bus: GainNode; // すべての音の入り口（ここから先は共通の加工）
let reverbIn: GainNode; // 残響へ送る入り口
let reverbReturn: GainNode;
let hallIn: GainNode; // 広い所の響きへ送る入り口
let boomBus: GainNode; // 特大の一撃の出口（全体のコンプレッサーを通さない）
let slowFilter: BiquadFilterNode; // スロー中に全体をこもらせる
let worldGain: GainNode; // パリィで世界が止まっている間、ここで世界の音（残響の尾も）を消す
let parryBus: GainNode; // パリィの音だけはこもりも消音も通さず、コンプレッサーへ直接出す
let master: GainNode | null = null; // 最後の出口。オプションの音量をここで掛ける
const bank: Record<string, AudioBuffer[]> = {};
const reversedBank: Record<string, AudioBuffer[]> = {};
const lastPick: Record<string, number> = {};

// オプションの音量（0〜1）。耳の感じ方に合わせて 2 乗した値を、ゲームと UI の両方の出口に掛ける
let masterVolume = 1;
export function setMasterVolume(v: number) {
  masterVolume = v;
  if (master) master.gain.value = v * v;
  if (uiMaster) uiMaster.gain.value = v * v;
}

// スローの深さ（0 = 通常, 1 = 最大）。素材の再生速度を落として、音も引き伸ばす
let slowAmt = 0;

export function ensureAudio() {
  if (!ctx) {
    ctx = new AudioContext();
    noiseBuffer = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
    const d = noiseBuffer.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;

    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.knee.value = 8;
    comp.ratio.value = 4;
    comp.attack.value = 0.002;
    comp.release.value = 0.15;
    slowFilter = ctx.createBiquadFilter();
    slowFilter.type = 'lowpass';
    slowFilter.frequency.value = 20000;
    slowFilter.Q.value = 0.9;
    bus = ctx.createGain();
    worldGain = ctx.createGain();
    master = ctx.createGain();
    master.gain.value = masterVolume * masterVolume;
    bus.connect(worldGain).connect(slowFilter).connect(comp).connect(master).connect(ctx.destination);
    parryBus = ctx.createGain();
    parryBus.connect(comp);
    // 特大の一撃だけは、全体のコンプレッサーで潰さずに、割れない上限だけを掛けて出す
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -3;
    limiter.knee.value = 2;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.001;
    limiter.release.value = 0.25;
    boomBus = ctx.createGain();
    boomBus.connect(limiter).connect(master);

    const conv = ctx.createConvolver();
    conv.buffer = makeImpulse(ctx, 1.3);
    reverbIn = ctx.createGain();
    reverbReturn = ctx.createGain();
    reverbReturn.gain.value = 0.5;
    reverbIn.connect(conv).connect(reverbReturn).connect(worldGain);
    // 広い所の響き（ボスの登場の大きな一撃だけに使う）
    const hallConv = ctx.createConvolver();
    hallConv.buffer = makeHall(ctx, 3.2);
    hallIn = ctx.createGain();
    const hallReturn = ctx.createGain();
    hallReturn.gain.value = 0.6;
    hallIn.connect(hallConv).connect(hallReturn).connect(boomBus); // 大きな一撃の響きなので、潰さずに出す
    reverbConv = conv;
    hallConvNode = hallConv;
    if (liteAudio) routeReverb();

    startLoops(ctx);
    loadBank(ctx);
  }
  wantPaused = false;
  applyAudioPaused();
}

// 部屋の残響: 最初の数本の反射のあと、高い音から先に消えていくノイズの尾を作る
function makeImpulse(c: AudioContext, seconds: number) {
  const len = Math.floor(c.sampleRate * seconds);
  const ir = c.createBuffer(2, len, c.sampleRate);
  for (let ch = 0; ch < 2; ch++) {
    const d = ir.getChannelData(ch);
    let lp = 0;
    for (let i = 0; i < len; i++) {
      const t = i / c.sampleRate;
      // 時間が経つほど強くなまらせて、高音の残りを短くする
      const k = Math.min(0.95, 0.15 + t * 1.2);
      lp = lp * k + (Math.random() * 2 - 1) * (1 - k);
      d[i] = lp * Math.exp(-t * 4.2) * 2.2;
    }
    for (const [at, g] of [[0.011, 0.5], [0.019, 0.35], [0.027, 0.3], [0.041, 0.22], [0.053, 0.16]]) {
      d[Math.floor((at + ch * 0.003) * c.sampleRate)] += g * (Math.random() < 0.5 ? -1 : 1);
    }
  }
  return ir;
}

// 広い所の響き: ビルに囲まれた広場で鳴ったような、暗くゆっくり消える長い尾。遅れて返ってくる跳ね返りを数本混ぜる
function makeHall(c: AudioContext, seconds: number) {
  const len = Math.floor(c.sampleRate * seconds);
  const ir = c.createBuffer(2, len, c.sampleRate);
  for (let ch = 0; ch < 2; ch++) {
    const d = ir.getChannelData(ch);
    let lp = 0;
    for (let i = 0; i < len; i++) {
      const t = i / c.sampleRate;
      // 初めから高い音を強く削り、時間とともにさらにこもらせる
      const k = Math.min(0.985, 0.7 + t * 0.4);
      lp = lp * k + (Math.random() * 2 - 1) * (1 - k);
      d[i] = lp * Math.exp(-t * 1.5) * (t < 0.03 ? t / 0.03 : 1) * 4;
    }
    for (const [at, g] of [[0.09, 0.25], [0.21, 0.2], [0.37, 0.14], [0.6, 0.09]]) {
      const i0 = Math.floor((at + ch * 0.013) * c.sampleRate);
      for (let j = 0; j < 400; j++) d[i0 + j] += g * Math.exp(-j / 120) * (j % 2 ? -1 : 1) * 0.5; // 鈍い跳ね返り
    }
  }
  return ir;
}

async function loadBank(c: AudioContext) {
  try {
    const manifest: Record<string, string[]> = await (await fetch('./sfx/manifest.json', { cache: 'no-cache' })).json(); // 素材を足したとき古い一覧が残らないように
    await Promise.all(
      Object.entries(manifest).flatMap(([group, files]) =>
        files.map(async (file, i) => {
          const buf = await c.decodeAudioData(await (await fetch(`./sfx/${file}`)).arrayBuffer());
          (bank[group] ??= [])[i] = buf;
        }),
      ),
    );
    for (const group of ['focus', 'swish']) reversedBank[group] = bank[group].map((b) => reverseBuffer(c, b));
  } catch (e) {
    // 素材が読めなくても合成音だけで鳴らし続ける
    console.warn('効果音の素材を読み込めませんでした', e);
  }
}

function reverseBuffer(c: AudioContext, b: AudioBuffer) {
  const r = c.createBuffer(b.numberOfChannels, b.length, b.sampleRate);
  for (let ch = 0; ch < b.numberOfChannels; ch++) r.getChannelData(ch).set(b.getChannelData(ch).slice().reverse());
  return r;
}

const rand = (a: number, b: number) => a + Math.random() * (b - a);

// 同じ種類の中から、直前と違うものを選ぶ
function pick(group: string, reversed = false) {
  const list = (reversed ? reversedBank : bank)[group];
  if (!list || list.length === 0) return null;
  let i = Math.floor(Math.random() * list.length);
  if (list.length > 1 && i === lastPick[group]) i = (i + 1) % list.length;
  lastPick[group] = i;
  return list[i];
}

interface Layer {
  gain?: number;
  rate?: number; // 再生速度（= 高さ）
  jitter?: number; // 再生速度の揺れ幅（±割合）
  delay?: number; // 秒
  hp?: number;
  lp?: number;
  pan?: number; // -1〜1。省くと少しだけ左右に散らす
  reverb?: number; // 残響へ送る量
  hall?: number; // 広い所の響きへ送る量
  reversed?: boolean;
  cut?: number; // この秒数で尾を絞って止める（録音の長い響きを切る）
  out?: AudioNode; // 省くとバス
}

// 録音素材を 1 つ鳴らす
function sample(group: string, o: Layer = {}) {
  if (!ctx) return;
  const buf = pick(group, o.reversed);
  if (!buf) return;
  const t0 = ctx.currentTime + (o.delay ?? 0);
  const src = ctx.createBufferSource();
  src.buffer = buf;
  const j = o.jitter ?? 0.06;
  src.playbackRate.value = (o.rate ?? 1) * rand(1 - j, 1 + j) * (1 - 0.35 * slowAmt);
  let node: AudioNode = src;
  if (o.hp) node = node.connect(filter('highpass', o.hp));
  if (o.lp) node = node.connect(filter('lowpass', o.lp));
  const g = ctx.createGain();
  const level = (o.gain ?? 1) * rand(0.9, 1.05);
  g.gain.value = level;
  if (o.cut) {
    g.gain.setValueAtTime(level, t0 + o.cut * 0.4);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + o.cut);
  }
  const p = ctx.createStereoPanner();
  p.pan.value = o.pan ?? rand(-0.12, 0.12);
  node.connect(g).connect(p).connect(o.out ?? bus);
  if (o.reverb && !liteAudio) {
    const s = ctx.createGain();
    s.gain.value = o.reverb;
    p.connect(s).connect(reverbIn);
  }
  if (o.hall && !liteAudio) {
    // 響きへは cut で絞る前の音量のまま送る（絞った後も響きの尾は長く残る）
    const s = ctx.createGain();
    s.gain.value = o.hall * level;
    let pre: AudioNode = src;
    if (o.lp) pre = pre.connect(filter('lowpass', o.lp));
    pre.connect(s).connect(hallIn);
  }
  src.start(t0);
  if (o.cut) src.stop(t0 + o.cut + 0.02);
}

function filter(type: BiquadFilterType, freq: number, q = 0.7) {
  const f = ctx!.createBiquadFilter();
  f.type = type;
  f.frequency.value = freq;
  f.Q.value = q;
  return f;
}

// 合成: 帯域を絞ったノイズの破裂。周波数を f0 → f1 へ動かす
function noise(type: BiquadFilterType, f0: number, f1: number, peak: number, dur: number, o: { attack?: number; q?: number; delay?: number; out?: AudioNode; reverb?: number; shaper?: WaveShaperNode } = {}) {
  if (!ctx) return;
  const t0 = ctx.currentTime + (o.delay ?? 0);
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer;
  const f = ctx.createBiquadFilter();
  f.type = type;
  f.Q.value = o.q ?? 0.8;
  f.frequency.setValueAtTime(f0, t0);
  f.frequency.exponentialRampToValueAtTime(f1, t0 + dur);
  const g = ctx.createGain();
  const attack = o.attack ?? 0.003;
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(peak, t0 + attack);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  let node: AudioNode = src.connect(f);
  if (o.shaper) node = node.connect(o.shaper);
  node.connect(g).connect(o.out ?? bus);
  if (o.reverb) {
    const s = ctx.createGain();
    s.gain.value = o.reverb;
    g.connect(s).connect(reverbIn);
  }
  src.start(t0, Math.random() * 0.5);
  src.stop(t0 + dur + 0.02);
}

// 合成: 音程を f0 → f1 へ下げる（上げる）音
function tone(f0: number, f1: number, peak: number, dur: number, o: { type?: OscillatorType; delay?: number; attack?: number; out?: AudioNode } = {}) {
  if (!ctx) return;
  const t0 = ctx.currentTime + (o.delay ?? 0);
  const osc = ctx.createOscillator();
  osc.type = o.type ?? 'sine';
  osc.frequency.setValueAtTime(f0, t0);
  osc.frequency.exponentialRampToValueAtTime(f1, t0 + dur);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(peak, t0 + (o.attack ?? 0.005));
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  osc.connect(g).connect(o.out ?? bus);
  osc.start(t0);
  osc.stop(t0 + dur + 0.02);
}

// ---- 鳴り続ける音: 風切り・スライディングの擦れ・スロー中のうなり ----
let windGain: GainNode;
let windFilter: BiquadFilterNode;
let scrapeGain: GainNode;
let scrapeFilter: BiquadFilterNode;
let droneGain: GainNode;
let nextHeartbeat = 0;
let duckUntil = 0; // この時刻までは鳴り続ける音を沈める（銃声の直後）

function loopNoise(c: AudioContext) {
  const src = c.createBufferSource();
  src.buffer = noiseBuffer;
  src.loop = true;
  src.start();
  return src;
}

function startLoops(c: AudioContext) {
  // 風: 速いほど大きく、高く
  windFilter = filter('bandpass', 500, 0.6);
  windGain = c.createGain();
  windGain.gain.value = 0;
  loopNoise(c).connect(windFilter).connect(windGain).connect(bus);

  // 床を擦る音: ざらついた中高域と、低いゴロゴロを重ねる
  scrapeFilter = filter('bandpass', 1800, 1.4);
  scrapeGain = c.createGain();
  scrapeGain.gain.value = 0;
  const scrapeSrc = loopNoise(c);
  scrapeSrc.connect(scrapeFilter).connect(scrapeGain);
  const rumble = filter('lowpass', 220);
  const rumbleGain = c.createGain();
  rumbleGain.gain.value = 2.2;
  scrapeSrc.connect(rumble).connect(rumbleGain).connect(scrapeGain);
  scrapeGain.connect(bus);

  // スロー中の低いうなり
  droneGain = c.createGain();
  droneGain.gain.value = 0;
  for (const [f, g] of [[46, 0.6], [69.5, 0.25]]) {
    const osc = c.createOscillator();
    osc.frequency.value = f;
    const og = c.createGain();
    og.gain.value = g;
    osc.connect(og).connect(droneGain);
    osc.start();
  }
  loopNoise(c).connect(filter('lowpass', 160)).connect(droneGain);
  droneGain.connect(bus);
}

// 一時停止 / タイトルの間は、鳴っている音も残響も含めて時間ごと止める。
// suspend / resume は終わるまで state が変わらないので、止めてすぐ再開すると resume が飛ばされて音が消えたままになる。
// 望む状態を覚えておき、切り替えが終わるたびに合わせ直す
let wantPaused = false;
let switching = false;
function applyAudioPaused() {
  if (!ctx || switching) return;
  const c = ctx;
  let p: Promise<void> | null = null;
  if (wantPaused && c.state === 'running') p = c.suspend();
  else if (!wantPaused && c.state === 'suspended') p = c.resume();
  if (!p) return;
  switching = true;
  p.catch(() => {}).finally(() => { switching = false; applyAudioPaused(); });
}
export function setAudioPaused(paused: boolean) {
  wantPaused = paused;
  applyAudioPaused();
}

// 同じ音声ノードを次の試合でも使う場合、死亡やスローの状態を持ち越さない。
export function resetMatchAudio() {
  slowAmt = 0;
  duckUntil = 0;
  nextHeartbeat = 0;
  if (!ctx) return;
  const t = ctx.currentTime;
  for (const [param, value] of [
    [worldGain.gain, 1], [slowFilter.frequency, 20000], [reverbReturn.gain, 0.5],
    [windGain.gain, 0], [scrapeGain.gain, 0], [droneGain.gain, 0],
  ] as [AudioParam, number][]) {
    param.cancelScheduledValues(t);
    param.setValueAtTime(value, t);
  }
  stopStageRise();
}

export interface AudioState {
  speed: number; // 水平の速さ (m/s)
  airborne: boolean;
  sliding: boolean;
  focusing: boolean;
  timeScale: number;
}

// 毎フレーム呼ぶ。鳴り続ける音の量と、スローのこもり具合を動かす
export function updateAudio(s: AudioState) {
  if (!ctx) return;
  const t = ctx.currentTime;
  const k = 0.05; // 値を寄せる時定数（秒）
  const duck = t < duckUntil ? 0.25 : 1;

  slowAmt = Math.min(1, Math.max(0, (1 - s.timeScale) / 0.8));
  slowFilter.frequency.setTargetAtTime(20000 * Math.pow(1100 / 20000, slowAmt), t, k);
  reverbReturn.gain.setTargetAtTime(0.5 + 0.9 * slowAmt, t, k);

  const windT = Math.min(1, Math.max(0, (s.speed - 9) / 26));
  windGain.gain.setTargetAtTime(windT * windT * (s.airborne ? 0.22 : 0.15) * duck, t, duck < 1 ? 0.01 : 0.15);
  windFilter.frequency.setTargetAtTime(350 + windT * 1400 + (s.airborne ? 300 : 0), t, k);

  // 擦れは、ざらつきが出るよう毎フレーム少しだけ音量と高さを揺らす
  const scrapeT = s.sliding ? Math.min(1, s.speed / 16) : 0;
  scrapeGain.gain.setTargetAtTime(scrapeT * rand(0.05, 0.09) * duck, t, s.sliding ? 0.02 : 0.06);
  scrapeFilter.frequency.setTargetAtTime(900 + scrapeT * 1600 * rand(0.8, 1.2), t, 0.02);

  droneGain.gain.setTargetAtTime(s.focusing ? 0.12 * slowAmt : 0, t, 0.12);

  // 構えている間は鼓動を「ドクン」と鳴らす（実時間で刻む）
  if (s.focusing && slowAmt > 0.4) {
    if (t >= nextHeartbeat) {
      nextHeartbeat = t + 0.78;
      heartbeat();
    }
  } else {
    nextHeartbeat = t + 0.25;
  }
}

function heartbeat() {
  sample('thud_heavy', { gain: 0.55, rate: 0.7, lp: 260, pan: 0, jitter: 0.02 });
  tone(62, 38, 0.35, 0.18);
  sample('thud_heavy', { gain: 0.35, rate: 0.65, lp: 220, pan: 0, jitter: 0.02, delay: 0.19 });
  tone(56, 34, 0.22, 0.16, { delay: 0.19 });
}

// ---- 武器 ----

// 銃声: 装飾を削った、低く鈍い一撃。破裂音・跳ね返り・残響は付けず、
// 重い打撃の録音と、高さを急に落とす歪んだ低音（キックドラムのような胴鳴り）を芯にする。
// 高い成分はほとんど削り、録音の銃声は頭の一瞬だけ借りて銃らしさを残す。
// 撃った直後は環境音を沈めて、静けさを際立たせる。
// 重さの違う 3 段階を用意し、G キーで切り替えて聴き比べられるようにしている
export const GUN_VARIANTS = ['ドスッ（標準・鈍く短い）', 'ドゥン（重い）', 'ズドン（さらに重い）'] as const;
let gunVariant = 0;
export function cycleGunVariant() {
  gunVariant = (gunVariant + 1) % GUN_VARIANTS.length;
  return GUN_VARIANTS[gunVariant];
}

// 軽く歪ませて、低音に「芯の太さ」を足す
let thumpCurve: Float32Array<ArrayBuffer> | null = null;
function saturator(drive: number) {
  if (!thumpCurve) {
    thumpCurve = new Float32Array(1024);
    for (let i = 0; i < thumpCurve.length; i++) {
      const x = (i / (thumpCurve.length - 1)) * 2 - 1;
      thumpCurve[i] = Math.tanh(x * 3) / Math.tanh(3);
    }
  }
  const pre = ctx!.createGain();
  pre.gain.value = drive;
  const ws = ctx!.createWaveShaper();
  ws.curve = thumpCurve;
  ws.oversample = '2x';
  pre.connect(ws);
  return { in: pre, out: ws };
}

// 胴鳴り: 高い音から一気に低音へ落ちる正弦波。立ち上がりの「ド」と、尾を引く「ゥン」
function thump(f0: number, f1: number, peak: number, dur: number, drive: number, out: AudioNode, lp = 600) {
  const t0 = ctx!.currentTime;
  const osc = ctx!.createOscillator();
  osc.frequency.setValueAtTime(f0, t0);
  osc.frequency.exponentialRampToValueAtTime(f1 * 1.6, t0 + 0.035);
  osc.frequency.exponentialRampToValueAtTime(f1, t0 + dur);
  const g = ctx!.createGain();
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(peak, t0 + 0.002);
  g.gain.setValueAtTime(peak, t0 + 0.02);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  const sat = saturator(drive);
  osc.connect(g).connect(sat.in);
  sat.out.connect(filter('lowpass', lp)).connect(out);
  osc.start(t0);
  osc.stop(t0 + dur + 0.02);
}

// volume は 1 が自分の銃。敵の銃は距離に応じて小さくし、高い成分も削って遠くで鳴っている感じにする
// pan は左右の位置（-1 が左、1 が右）。敵の銃声を、敵のいる向きから聞こえるようにする
export function playGunshot(volume = 1, pan = 0) {
  if (!ctx) return;
  const v = rand(0.97, 1.03);
  // 響きを足さず、音を押しつぶして密度を上げるコンプ。
  // アタックを少し遅らせて、立ち上がりの一瞬はつぶさずに通し、輪郭をはっきりさせる
  const comp = ctx.createDynamicsCompressor();
  comp.threshold.value = -20;
  comp.knee.value = 3;
  comp.ratio.value = 6;
  comp.attack.value = 0.006;
  comp.release.value = 0.08;
  const out = ctx.createGain();
  out.gain.value = 1.7 * volume;
  // 聞こえない超低域のうなりを切って、低音の濁りを減らす
  const hp = comp.connect(filter('highpass', 40));
  const panner = ctx.createStereoPanner();
  panner.pan.value = pan;
  panner.connect(bus);
  if (volume < 1) hp.connect(filter('lowpass', 900 + 2500 * volume)).connect(out).connect(panner);
  else hp.connect(out).connect(panner);
  const dry = { pan: 0, jitter: 0.02, out: comp };

  if (gunVariant === 0) {
    // 詰まったような鈍く短い「ドスッ」。芯は鈍いまま、頭の輪郭だけをはっきり立てる
    thump(180 * v, 50, 1.0, 0.16, 2.6, comp, 1000);
    sample('punch_heavy', { ...dry, gain: 0.9, rate: 0.65 * v, lp: 1600, cut: 0.13 });
    sample('thud_heavy', { ...dry, gain: 0.75, rate: 0.7, lp: 1300, cut: 0.14 });
    sample('gun_body', { ...dry, gain: 0.3, hp: 300, lp: 2600, cut: 0.035 });
    noise('lowpass', 1600, 220, 0.4, 0.06, { attack: 0.001, out: comp });
    noise('bandpass', 2600, 1200, 0.28, 0.014, { attack: 0.0005, q: 1.2, out: comp }); // 一瞬の「パ」で発音の頭を示す
  } else if (gunVariant === 1) {
    // 腹に響く「ドゥン」
    thump(150 * v, 38, 1.0, 0.34, 2.2, comp);
    sample('thud_heavy', { ...dry, gain: 1.0, rate: 0.62 * v, lp: 900, cut: 0.3 });
    sample('punch_heavy', { ...dry, gain: 0.6, rate: 0.55, lp: 800, cut: 0.2 });
    sample('gun_sub', { ...dry, gain: 0.6, rate: 0.85, lp: 240, cut: 0.35 });
    sample('gun_body', { ...dry, gain: 0.16, hp: 120, lp: 1200, cut: 0.04 });
    noise('lowpass', 900, 120, 0.35, 0.12, { attack: 0.001, out: comp }); // 空気が押し出される鈍い圧
  } else {
    // 大口径の「ズドン」。胴鳴りをより低く長く、もう一段遅れて重さが沈み込む
    thump(120 * v, 30, 1.0, 0.48, 3, comp, 450);
    thump(70 * v, 24, 0.5, 0.42, 1.5, comp, 300);
    sample('thud_heavy', { ...dry, gain: 1.1, rate: 0.5 * v, lp: 700, cut: 0.4 });
    sample('punch_heavy', { ...dry, gain: 0.7, rate: 0.45, lp: 600, cut: 0.25 });
    sample('gun_sub', { ...dry, gain: 0.75, rate: 0.7, lp: 200, cut: 0.45 });
    sample('gun_body', { ...dry, gain: 0.12, hp: 100, lp: 900, cut: 0.04 });
    noise('lowpass', 700, 80, 0.45, 0.18, { attack: 0.001, out: comp });
  }
  if (volume < 1) return; // 撃鉄の手応えと静けさは自分の銃だけ
  sample('metal_tick', { gain: 0.05, rate: 0.75, lp: 2000 }); // 撃鉄の小さな手応え
  duckUntil = ctx.currentTime + 0.55;
}

// 自分が撃たれた: 体に響く鈍い「ドッ」だけ。高い音は付けない
export function playHurt() {
  if (!ctx) return;
  sample('thud_heavy', { gain: 0.8, rate: 0.8, lp: 700 });
  sample('punch_heavy', { gain: 0.45, rate: 0.6, lp: 900 });
  tone(110, 36, 0.7, 0.22, { attack: 0.004 });
  duckUntil = ctx.currentTime + 0.4;
}

export interface SwishParams {
  at?: number; // 呼ぶ側のタイミング用（ここでは使わない）
  dur: number;
  f0: number;
  f1: number;
  gain: number;
}
export type SwishKind = 'kunai' | 'sword' | 'talon' | 'gun' | 'sickle' | 'axe' | 'talonAxe' | 'talonSickle' | 'talonGun' | 'talonKunai' | 'bat';

// 風切り音: ノイズを帯域フィルタに通し、振りの速さに合わせて高さと音量を山なりに動かす。
// そこへ録音の振り音を、合成の山に合わせて少し遅らせて重ねる。剣は刃が空気を裂く「シュイン」も足す。
// 鎌は全体を高く細くして、薄い刃が鋭く空気を切る「ヒュイン」にし、振り抜きの頂点に澄んだ金属のきらめきを添える。
// 剣のスキン「爪」（talon）は、剣の録音を低く暗く重くする。斧の「爪」（talonAxe）は、斧の音の下に低く暗い金属の唸りを足す。鎖鎌の「爪」（talonSickle）は、鎌の音の下に暗い刃の鳴りを敷く。リボルバーの「爪」（talonGun）は、回す音を低く暗くする。クナイの「爪」（talonKunai）は、振り音を少し低く暗くして刃の鳴りを薄く敷く
export function playSwish(s: SwishParams, kind: SwishKind = 'kunai') {
  if (!ctx) return;
  const t0 = ctx.currentTime;
  const sickle = kind === 'sickle' || kind === 'talonSickle';
  const axe = kind === 'axe' || kind === 'talonAxe';
  const bat = kind === 'bat';
  const v = rand(0.9, 1.1) * (sickle ? 1.6 : axe ? 0.55 : bat ? 0.7 : 1);
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer;
  const bp = ctx.createBiquadFilter();
  bp.type = 'bandpass';
  bp.Q.value = sickle ? 2.2 : axe || bat ? 0.8 : 1.2;
  bp.frequency.setValueAtTime(s.f0 * v, t0);
  bp.frequency.exponentialRampToValueAtTime(s.f1 * v, t0 + s.dur * 0.45);
  bp.frequency.exponentialRampToValueAtTime(s.f0 * 0.7 * v, t0 + s.dur);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(s.gain, t0 + s.dur * 0.4);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + s.dur);
  src.connect(bp).connect(g).connect(bus);
  src.start(t0, Math.random() * 0.5);
  src.stop(t0 + s.dur + 0.05);

  // 振りが速い（高い）ほど、録音も速く回す
  const speed = Math.min(1.5, Math.max(0.6, s.f1 / 1700));
  const at = s.dur * 0.3;
  if (kind === 'talon') {
    // 剣の録音を、黒い機械の刀に合わせて少し低く暗くする。下には同じ刃の録音をずっと低く回して敷き、重さを足す
    sample('blade', { gain: Math.min(0.85, s.gain * 1.3), rate: 0.75 * speed, delay: at * 0.6, lp: 6000, reverb: 0.14 });
    sample('blade', { gain: Math.min(0.45, s.gain * 0.8), rate: 0.5 * speed, delay: at * 0.6, lp: 2500, cut: s.dur * 1.4 });
    sample('swish', { gain: Math.min(0.8, s.gain * 1.2), rate: 0.6 * speed, delay: at, lp: 5000, reverb: 0.1 });
  } else if (kind === 'sword') {
    sample('blade', { gain: Math.min(0.9, s.gain * 1.3), rate: 0.85 * speed, delay: at * 0.6, lp: 9000, reverb: 0.12 });
    sample('swish', { gain: Math.min(0.8, s.gain * 1.2), rate: 0.7 * speed, delay: at, reverb: 0.08 });
  } else if (axe) {
    // 斧は厚い頭が空気を押しのける、低く太い「ブォン」。録音を遅く回して低い帯域だけ残す。
    // 遅く回すと録音が 2〜3 倍に伸びるので、振りの録音の山（元の 0.03 秒あたり）を合成の山（s.dur * 0.4）に合わせ、
    // どちらも振りの長さで切る（切らないと刃の録音が 1 秒近く尾を引き、次の振りにかぶる）
    const end = s.dur * 1.05;
    const swishRate = 0.5 * speed;
    const swishAt = Math.max(0, s.dur * 0.4 - 0.03 / swishRate);
    sample('swish', { gain: Math.min(0.8, s.gain * 1.4), rate: swishRate, delay: swishAt, lp: 2200, reverb: 0.1, cut: end - swishAt });
    sample('blade', { gain: Math.min(0.4, s.gain * 0.6), rate: 0.55 * speed, delay: at * 0.8, lp: 3000, cut: end - at * 0.8 });
    noise('lowpass', 500, 260, Math.min(0.3, s.gain * 0.5), s.dur * 1.1, { attack: s.dur * 0.35 });
    // 爪: 刃の録音をさらに遅く回して暗く敷き、重い機械の刃が唸るようにする
    if (kind === 'talonAxe') sample('blade', { gain: Math.min(0.45, s.gain * 0.8), rate: 0.38 * speed, delay: at * 0.6, lp: 1600, reverb: 0.14, cut: end - at * 0.6 });
  } else if (bat) {
    // バットは丸い筒が空気を押しのける「ブン」。斧より軽く高く、刃の鳴りは入れない
    sample('swish', { gain: Math.min(0.8, s.gain * 1.5), rate: 0.75 * speed, delay: at, lp: 3500, reverb: 0.06, cut: s.dur * 1.2 });
    noise('lowpass', 700, 300, Math.min(0.25, s.gain * 0.4), s.dur, { attack: s.dur * 0.35 });
  } else if (sickle) {
    sample('blade_hi', { gain: Math.min(0.85, s.gain * 1.5), rate: 1.15 * speed, delay: at * 0.5, hp: 1500, reverb: 0.1 });
    sample('blade', { gain: Math.min(0.5, s.gain * 0.8), rate: 1.3 * speed, delay: at * 0.7, hp: 2500, reverb: 0.08 });
    sample('swish', { gain: Math.min(0.6, s.gain * 1.1), rate: 1.2 * speed, delay: at, hp: 900 });
    // 振り抜きの頂点の「キィン」: ごく短い高い帯域のノイズと、高く短い金属音
    noise('bandpass', 7000, 12000, Math.min(0.12, s.gain * 0.3), 0.07, { q: 3, attack: 0.004, delay: s.dur * 0.42, reverb: 0.15 });
    if (s.gain >= 0.2) setTimeout(() => playRing(2.1, 0.3, 0.09), s.dur * 420);
    // 爪: 刃の録音を遅く回して暗く敷き、黒い機械の刃の重さを足す
    if (kind === 'talonSickle') sample('blade', { gain: Math.min(0.4, s.gain * 0.7), rate: 0.6 * speed, delay: at * 0.6, lp: 2500, reverb: 0.12, cut: s.dur * 1.2 });
  } else if (kind === 'talonKunai') {
    sample('swish', { gain: Math.min(0.7, s.gain * 1.8), rate: speed * 0.85, delay: at, lp: 5000, reverb: 0.08 });
    sample('blade', { gain: Math.min(0.3, s.gain * 0.5), rate: 0.7 * speed, delay: at * 0.6, lp: 2500, cut: s.dur * 1.2 });
  } else if (kind === 'talonGun') {
    sample('swish', { gain: Math.min(0.7, s.gain * 1.8), rate: speed * 0.9, delay: at, lp: 4500, reverb: 0.1 });
    sample('blade', { gain: Math.min(0.35, s.gain * 0.6), rate: 0.55 * speed, delay: at * 0.6, lp: 2000, cut: s.dur * 1.2 });
  } else {
    sample('swish', { gain: Math.min(0.7, s.gain * 1.8), rate: speed * (kind === 'gun' ? 1.15 : 1), delay: at });
  }
}

export type HitKind = 'kunai' | 'sword' | 'throw' | 'bullet' | 'axe' | 'bat';

// ヒット音: 「ザシュッ」（刃が入る録音と高い帯域のノイズ）に、「ドン」（殴打の録音と音程を下げるサイン波）、
// 頭の「カッ」（ごく短い高音のノイズ）を重ねる。power が大きいほど低く長く、重い打撃と残響も足す
export function playHit(power: number, kind: HitKind) {
  if (!ctx) return;
  const v = rand(0.9, 1.1);
  const heavy = Math.min(1, Math.max(0, (power - 1) / 0.7)); // 0（通常）〜 1（締めの技）
  const out = ctx.createGain();
  out.gain.value = 0.8;
  out.connect(bus);
  const verb = 0.1 + 0.35 * heavy;

  if (kind === 'bullet') {
    sample('punch', { gain: 0.75, rate: 0.85, out });
    sample('thud_heavy', { gain: 0.6, rate: 1.1, out });
  } else if (kind === 'axe') {
    // 斧: 刃が深く食い込む「ゴシャッ」。低く遅い斬撃に、重い殴打と鈍い金属の鳴りを厚く重ねる
    sample('slice', { gain: 0.75, rate: 0.6 * (1 - 0.1 * heavy), out, reverb: verb });
    sample('punch_heavy', { gain: 0.8, rate: 0.8 - 0.1 * heavy, out, reverb: verb });
    sample('thud_heavy', { gain: 0.6, rate: 0.85, out, reverb: 0.15 });
    sample('clash', { gain: 0.16, rate: 0.5, lp: 3500, out, reverb: verb });
    sample('plank', { gain: 0.3, rate: 0.7, lp: 4000, out }); // 割れる「バキッ」
  } else if (kind === 'bat') {
    // バット: 金属の筒が体を叩く「ゴッ」。重い殴打に、中空の金属の鈍い鳴りを短く添える（刃が入る音は入れない）
    sample('punch_heavy', { gain: 0.85, rate: 0.9 - 0.1 * heavy, out, reverb: verb });
    sample('thud_heavy', { gain: 0.6, rate: 1, out, reverb: 0.12 });
    sample('metal_small', { gain: 0.3, rate: 0.7, lp: 4000, out, reverb: verb });
    sample('clash', { gain: 0.1, rate: 0.6, lp: 2500, out });
  } else {
    const blade = kind === 'sword';
    sample('slice', { gain: blade ? 0.7 : 0.55, rate: (blade ? 0.85 : 1.1) * (1 - 0.15 * heavy), out, reverb: verb });
    sample(heavy > 0.3 ? 'punch_heavy' : 'punch', { gain: 0.55 + 0.35 * heavy, rate: 1 - 0.15 * heavy, out, reverb: verb });
    if (blade) sample('clash', { gain: 0.14 + 0.1 * heavy, rate: 0.75, lp: 6000, out, reverb: verb }); // 刃の金属的な鳴り
    if (kind === 'throw') sample('wood', { gain: 0.35, rate: 1.2, out }); // 刺さった「トッ」
  }
  if (heavy > 0) {
    sample('thud_heavy', { gain: 0.7 * heavy, rate: 0.75, out, reverb: 0.3 });
    sample('gun_sub', { gain: 0.45 * heavy, rate: 1.3, out });
  }

  // 斬撃のノイズ
  const slashDur = 0.12 + 0.1 * heavy;
  noise('bandpass', 5200 * v, 1400 * v, kind === 'bullet' || kind === 'bat' ? 0.2 : 0.4, slashDur, { q: 0.9, attack: 0.004, out });
  // 頭の鋭い当たり
  noise('highpass', 3000, 3000, 0.4, 0.025, { attack: 0.001, out });
  // 低い衝撃
  const thumpDur = 0.14 + 0.16 * heavy;
  tone((170 - 50 * heavy) * v, 42, 0.6 + 0.3 * heavy, thumpDur, { attack: 0.006, out });
}

// 斧が地面を叩いた: 硬い床に重い鉄が当たる「ドゴッ」。空振りでも重さが伝わるように
export function playAxeGround(power = 1) {
  if (!ctx) return;
  sample('thud_heavy', { gain: 0.6 * power, rate: 0.7, reverb: 0.2 });
  sample('plate', { gain: 0.22 * power, rate: 0.6, lp: 2500 });
  sample('gun_sub', { gain: 0.35 * power, rate: 1.4 });
  noise('lowpass', 900, 120, 0.3 * power, 0.25, { attack: 0.003 });
  tone(95, 38, 0.5 * power, 0.3, { attack: 0.004 });
}

// ---- 船（SHIP） ----
// 大波の予告の汽笛: 低く太い 2 つの音を重ねて長く鳴らす。遠くの船から聞こえるように、残響を多めにする
export function playShipHorn(volume = 1) {
  if (!ctx) return;
  const lp = filter('lowpass', 900); // のこぎり波の角を丸めて、ラッパのような太い音にする
  lp.connect(panOut(0));
  for (const [f, g] of [[73, 0.2], [110, 0.14], [146, 0.05]] as const) {
    tone(f, f * 0.985, g * volume, 2.4, { type: 'sawtooth', attack: 0.35, out: lp });
  }
  noise('lowpass', 300, 200, 0.05 * volume, 2.2, { attack: 0.4, reverb: 0.4 });
}
// 船体のきしみ: 大きく傾いていくときの、鉄がたわむ低い「ギギィ」
export function playHullCreak(volume = 1) {
  if (!ctx) return;
  sample('gear', { gain: 0.22 * volume, rate: 0.28, lp: 900, cut: 0.9, reverb: 0.3 });
  sample('plate', { gain: 0.1 * volume, rate: 0.3, lp: 700, delay: 0.25, cut: 0.6, reverb: 0.3 });
  tone(52, 44, 0.12 * volume, 1.4, { type: 'triangle', attack: 0.5 });
}
// 積み荷が手すりにぶつかった「ガゴォン」。power は 0..1（速いほど大きい）、volume は遠いほど小さく
export function playCargoSlam(power: number, volume = 1, pan = 0) {
  if (!ctx) return;
  const out = panOut(pan);
  const v = power * volume;
  sample('thud_heavy', { gain: 0.7 * v, rate: 0.5, reverb: 0.3, pan });
  sample('plate', { gain: 0.3 * v, rate: 0.4, lp: 1800, cut: 0.6, reverb: 0.3, pan });
  noise('lowpass', 600, 90, 0.3 * v, 0.4, { attack: 0.004, out });
  tone(70, 32, 0.5 * v, 0.45, { attack: 0.004, out });
}

// 近接の空振りが壁や床を叩いた（weapons/wallHit.ts）。肉に入る「ザシュッ」は入れず、硬い面に弾かれた乾いた音だけ。
// 刃は短い金属の「キッ」、斧は重い「ガゴッ」、バットは中空の「カンッ」
export function playWallHit(kind: 'blade' | 'heavy' | 'blunt', power = 1) {
  if (!ctx) return;
  if (kind === 'blade') {
    sample('clash', { gain: 0.2 * power, rate: rand(1.05, 1.25), lp: 7000, cut: 0.18, reverb: 0.08 });
    sample('step_hard', { gain: 0.35 * power, rate: rand(0.85, 1), lp: 2500, cut: 0.12 });
    noise('highpass', 4000, 4000, 0.25 * power, 0.02, { attack: 0.001 });
  } else if (kind === 'heavy') {
    sample('step_hard', { gain: 0.5 * power, rate: rand(0.6, 0.7), lp: 1800, cut: 0.2, reverb: 0.12 });
    sample('thud_heavy', { gain: 0.4 * power, rate: 0.85 });
    sample('clash', { gain: 0.12 * power, rate: 0.55, lp: 3000, cut: 0.3 });
    noise('lowpass', 1400, 250, 0.2 * power, 0.18, { attack: 0.003, delay: 0.005 });
  } else {
    sample('metal_small', { gain: 0.3 * power, rate: rand(0.75, 0.85), lp: 4500, cut: 0.25, reverb: 0.08 });
    sample('step_hard', { gain: 0.4 * power, rate: rand(0.75, 0.85), lp: 2200, cut: 0.15 });
    sample('thud', { gain: 0.25 * power, rate: 0.9, lp: 900, cut: 0.12 });
  }
}

// とどめで砕け散る: 低く重い「ドッ」に、低く落としたガラスの割れる音を乾いたまま重ねる
// 連続するたびに半音ずつ上げ、極端に高くならないよう 1 オクターブで止める。
function killPitch(chain: number) {
  return 2 ** (Math.min(12, Math.max(0, chain - 1)) / 12);
}
export function playKill(chain = 1) {
  if (!ctx) return;
  const pitch = killPitch(chain);
  sample('thud_heavy', { gain: 0.9, rate: 0.6 * pitch, reverb: 0.15 });
  sample('glass', { gain: 0.45, rate: 0.55 * pitch, lp: 5000, cut: 0.5 });
  if (liteAudio) return;
  sample('gun_sub', { gain: 0.6, rate: 0.9 * pitch });
  sample('glass', { gain: 0.3, rate: 0.8 * pitch, lp: 7000, delay: 0.03, cut: 0.35 });
  noise('lowpass', 1800, 300, 0.35, 0.3, { attack: 0.003 });
  tone(95 * pitch, 30 * pitch, 0.9, 0.45, { attack: 0.004 });
}

// 最後の 1 体: 砕けた瞬間に世界の音をすべて消し、砕ける一撃だけを乾いたまま太く鳴らす。
// 止まっている間は細い耳鳴りだけを残し、明ける瞬間に腹へ沈む低い「ドォン」と長い地鳴りを落とす。
// 世界の音はスローが明けるのに合わせてゆっくり戻す。どれもこもりを通さない parryBus へ出す
export function playFinale(freeze: number, chain = 1) {
  if (!ctx) return;
  const pitch = killPitch(chain);
  const t0 = ctx.currentTime;
  worldGain.gain.cancelScheduledValues(t0);
  worldGain.gain.setValueAtTime(worldGain.gain.value, t0);
  worldGain.gain.linearRampToValueAtTime(0, t0 + 0.01);
  worldGain.gain.setValueAtTime(0, t0 + freeze + 0.5);
  worldGain.gain.linearRampToValueAtTime(1, t0 + freeze + 2.2);
  const out = parryBus;
  const dry = { out, pan: 0, jitter: 0.02 };

  // 砕ける一撃: 鋭い頭・重い胴・低く落としたガラス・鉄板の重さ
  sample('gun_crack', { ...dry, gain: 0.4, rate: 0.6 * pitch, lp: 5000, cut: 0.1 });
  sample('punch_heavy', { ...dry, gain: 0.95, rate: 0.5 * pitch });
  sample('thud_heavy', { ...dry, gain: 1.0, rate: 0.5 * pitch, lp: 1400 });
  sample('glass', { ...dry, gain: 0.55, rate: 0.5 * pitch, lp: 5000, cut: 0.6 });
  sample('glass', { ...dry, gain: 0.35, rate: 0.72 * pitch, lp: 7000, delay: 0.03, cut: 0.45, pan: 0.2 });
  sample('plate', { ...dry, gain: 0.28, rate: 0.4 * pitch, lp: 2500, cut: 0.5 });
  noise('lowpass', 2400, 200, 0.45, 0.35, { attack: 0.002, out });
  tone(110 * pitch, 28 * pitch, 1.0, 0.5, { attack: 0.003, out });

  // 止まっている間の耳鳴り: わずかにずらした 2 本の高いサイン波を、ふくらませてから細く消す
  for (const [freq, gain] of [[3950, 0.02], [3963, 0.014]]) {
    const osc = ctx.createOscillator();
    osc.frequency.value = freq;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.12);
    g.gain.setValueAtTime(gain, t0 + freeze);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + freeze + 1.6);
    osc.connect(g).connect(out);
    osc.start(t0);
    osc.stop(t0 + freeze + 1.7);
  }

  // 明ける瞬間の「ドォン」と、長く沈んでいく地鳴り
  sample('thud_heavy', { ...dry, gain: 0.95, rate: 0.4, lp: 600, delay: freeze });
  sample('gun_sub', { ...dry, gain: 0.85, rate: 0.6, delay: freeze });
  sample('punch_heavy', { ...dry, gain: 0.5, rate: 0.42, lp: 700, delay: freeze });
  tone(72, 22, 0.95, 1.5, { attack: 0.004, out, delay: freeze });
  noise('lowpass', 600, 40, 0.32, 2.4, { attack: 0.02, out, delay: freeze });
  // 遠くで鳴る鐘を一つ、低く
  sample('bell', { ...dry, gain: 0.22, rate: 0.5, lp: 3000, delay: freeze + 0.06 });
}

// 倒れた: 世界の音を引いて、体に沈む鈍い一打と、長くこもった地鳴りと耳鳴りだけを残す。世界の音は戻さない
// （戻すのはステージに入り直したとき = 読み込み直したとき）
export function playDeath() {
  if (!ctx) return;
  const t0 = ctx.currentTime;
  worldGain.gain.cancelScheduledValues(t0);
  worldGain.gain.setValueAtTime(worldGain.gain.value, t0);
  worldGain.gain.linearRampToValueAtTime(0, t0 + 0.6);
  const out = parryBus;
  const dry = { out, pan: 0, jitter: 0.02 };
  sample('thud_heavy', { ...dry, gain: 1.0, rate: 0.45, lp: 600 });
  sample('punch_heavy', { ...dry, gain: 0.7, rate: 0.45, lp: 700 });
  sample('gun_sub', { ...dry, gain: 0.8, rate: 0.5 });
  tone(90, 24, 1.0, 1.8, { attack: 0.004, out });
  noise('lowpass', 500, 40, 0.3, 3, { attack: 0.03, out });
  // 倒れきったときの、床に落ちる鈍い音
  sample('thud', { ...dry, gain: 0.5, rate: 0.55, lp: 500, delay: 0.75 });
  for (const [freq, gain] of [[3200, 0.016], [3211, 0.011]]) {
    const osc = ctx.createOscillator();
    osc.frequency.value = freq;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.3);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + 3.2);
    osc.connect(g).connect(out);
    osc.start(t0);
    osc.stop(t0 + 3.3);
  }
}

// ゲームオーバーの見出しを落とす、低くこもった「ドゥン」
export function playGameOver() {
  uiClick('bandpass', 2200, 500, 0.12, 0.06);
  uiClick('lowpass', 1600, 60, 0.4, 0.9);
  uiTone(70, 24, 0.9, 1.4);
}

// スコアの音は画面の表示なので、スローのこもりも引き伸ばしも通さず、いつも同じ高さで鳴らす
const uiRate = (r: number) => r / (1 - 0.35 * slowAmt);

// スコアの倍率が 1 つ足された「チッ」: 小さく乾いた金属音。段が進むほど少しずつ高く、強くする
export function playScoreTick(step: number) {
  if (!ctx) return;
  const k = Math.min(step, 6);
  sample('metal_tick', { gain: 0.16 + 0.03 * k, rate: uiRate(0.85 + 0.07 * k), jitter: 0.015, lp: 7000, out: parryBus, pan: 0.15 });
  if (step > 0) sample('metal_small', { gain: 0.08 + 0.015 * k, rate: uiRate(1.1 + 0.06 * k), jitter: 0.02, cut: 0.12, out: parryBus, pan: 0.15 });
}

// スコアの確定「ドッ」: 低くこもらせた重い一打。足した倍率が多いほど少しだけ太くする
export function playScoreSlam(steps: number) {
  if (!ctx) return;
  const k = Math.min(steps, 4) / 4;
  sample('thud_heavy', { gain: 0.3 + 0.2 * k, rate: uiRate(0.8 - 0.1 * k), lp: 700, jitter: 0.02, out: parryBus, pan: 0.1 });
  sample('metal_small', { gain: 0.14, rate: uiRate(0.6), jitter: 0.02, cut: 0.25, out: parryBus, pan: 0.15 });
}

// パリィ: 弾いた瞬間に世界の音を消し、高い「キィン」の余韻だけを残す。
// 止まっていた時間が明ける瞬間に、低く重い「ドンッ」と一緒に世界の音を戻す
export function playParry(freeze: number) {
  if (!ctx) return;
  const t0 = ctx.currentTime;
  worldGain.gain.cancelScheduledValues(t0);
  worldGain.gain.setValueAtTime(worldGain.gain.value, t0);
  worldGain.gain.linearRampToValueAtTime(0.02, t0 + 0.012);
  worldGain.gain.setValueAtTime(0.02, t0 + freeze);
  worldGain.gain.linearRampToValueAtTime(1, t0 + freeze + 0.12);

  // 弾いた「カキン」: 刃と弾がぶつかる短い金属音
  sample('clash', { gain: 0.5, rate: 1.25, hp: 1500, out: parryBus, jitter: 0.03 });
  noise('highpass', 4000, 6000, 0.25, 0.03, { attack: 0.001, out: parryBus });
  // 長く残る「キィン」: 倍音の揃わないサイン波を、わずかにうならせながらゆっくり消す
  for (const [freq, gain, decay] of [[2480, 0.07, 1.6], [2493, 0.05, 1.4], [3720, 0.03, 1.0], [5910, 0.012, 0.6]]) {
    const osc = ctx.createOscillator();
    osc.frequency.value = freq;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + decay);
    osc.connect(g).connect(parryBus);
    osc.start(t0);
    osc.stop(t0 + decay + 0.05);
  }

  // 明ける瞬間の「ドンッ」
  sample('thud_heavy', { gain: 0.75, rate: 0.6, lp: 500, out: parryBus, delay: freeze, jitter: 0.02 });
  sample('gun_sub', { gain: 0.55, rate: 0.8, out: parryBus, delay: freeze });
  tone(90, 32, 0.7, 0.4, { attack: 0.004, out: parryBus, delay: freeze });
  noise('lowpass', 900, 120, 0.25, 0.35, { attack: 0.004, out: parryBus, delay: freeze });
}

// 回したときの金属音:倍音の揃わないサイン波を重ねて短く減衰させる
export function playRing(pitch = 1, volume = 1, decay = 0.35) {
  if (!ctx) return;
  const t0 = ctx.currentTime;
  for (const [freq, gain] of [[3150, 0.05], [4720, 0.03], [6930, 0.015]]) {
    const osc = ctx.createOscillator();
    osc.frequency.value = freq * pitch * (1 - 0.35 * slowAmt);
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain * volume, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + decay);
    osc.connect(g).connect(bus);
    osc.start(t0);
    osc.stop(t0 + decay + 0.05);
  }
}

// 握り直したときの「チャキッ」: 高く短い金属音を 2 つ、わずかにずらして重ね、録音の小さな金属音を添える
// ライフルの銃声: リボルバーの銃声をそのまま土台にして、頭に鋭い破裂音を、下に低く長い胴鳴りを 1 本ずつ足す。
// 尾は広い所の響きへ逃がして、大きな銃に聞かせる。響きへ送るだけにして、鳴った瞬間の音には何も重ねない（重ねると輪郭がぼける）
export function playRifleShot() {
  if (!ctx) return;
  playGunshot(1.15);
  const dry = { pan: 0, jitter: 0.015 };
  sample('gun_crack', { ...dry, gain: 0.45, rate: 0.95, hp: 1500, cut: 0.08, hall: 0.5 });
  thump(95, 30, 0.55, 0.4, 1.4, bus, 240);
  sample('thud_heavy', { ...dry, gain: 0.3, rate: 0.5, lp: 600, delay: 0.02, cut: 0.3, hall: 1.0 });
  duckUntil = ctx.currentTime + 1.1;
}
// ライフルのヘッドショット: 頭を撃ち抜いた高く澄んだ「キンッ」と、殻が割れる乾いた「パキッ」。
// スローでこもらせず遠くからでも聞こえるよう parryBus へ出す。kill なら低い「ドッ」と短い余韻の鐘を重ねる
export function playHeadshot(kill: boolean) {
  if (!ctx) return;
  const t0 = ctx.currentTime;
  const dry = { out: parryBus, pan: 0, jitter: 0.02 };
  sample('clash', { ...dry, gain: 0.45, rate: 1.6, hp: 2500, cut: 0.12 });
  sample('metal_tick', { ...dry, gain: 0.5, rate: 1.3, hp: 1500 });
  sample('glass', { ...dry, gain: 0.4, rate: 1.1, hp: 1200, cut: 0.25 });
  noise('highpass', 5000, 7000, 0.3, 0.02, { attack: 0.0005, out: parryBus });
  for (const [freq, gain, decay] of [[3300, 0.05, 0.5], [3317, 0.035, 0.45], [4950, 0.02, 0.3]]) {
    const osc = ctx.createOscillator();
    osc.frequency.value = freq;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain * (kill ? 1 : 0.6), t0 + 0.003);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + decay);
    osc.connect(g).connect(parryBus);
    osc.start(t0);
    osc.stop(t0 + decay + 0.05);
  }
  if (!kill) return;
  sample('punch_heavy', { ...dry, gain: 0.7, rate: 0.7, lp: 1500, delay: 0.01 });
  sample('glass', { ...dry, gain: 0.35, rate: 0.6, lp: 6000, delay: 0.02, cut: 0.4 });
  sample('bell', { ...dry, gain: 0.16, rate: 1.4, lp: 6000, delay: 0.03 });
  tone(130, 40, 0.6, 0.3, { attack: 0.003, out: parryBus, delay: 0.01 });
}

// ライフルのレバーを下げる（open）・戻す（close）
export function playLever(phase: 'open' | 'close') {
  if (phase === 'open') {
    sample('gun_latch', { gain: 0.55, rate: 0.75 });
    sample('metal_small', { gain: 0.25, rate: 0.9, delay: 0.02 });
  } else {
    sample('gun_latch', { gain: 0.6, rate: 0.95 });
    sample('metal_tick', { gain: 0.4, rate: 0.75, delay: 0.015 });
  }
}

// 装填の音は響かせない: 金属の録音は頭だけ残してすぐ切り、高い鳴りを削って、乾いた小さなクリックにする
// ライフルを傾けて装填口を見せる: 服の擦れと、銃が手の中で向きを変える鈍い音
export function playRifleTilt() {
  sample('cloth', { gain: 0.24, rate: 1.05 });
  sample('thud', { gain: 0.14, rate: 1.3, lp: 900, delay: 0.12, cut: 0.1 });
}
// 1 発を指でつまみ上げる: 指先が真鍮に触れるかすかな「チッ」
export function playRifleRoundPick() {
  sample('cloth', { gain: 0.08, rate: 1.6, cut: 0.1 });
  noise('highpass', 3500, 3500, 0.025, 0.012, { attack: 0.001, delay: 0.03 });
}
// 弾の先が装填口の蓋を押し開ける小さな「カチ」と、真鍮が擦れて奥へ滑る「スッ」
export function playRifleGate() {
  sample('metal_tick', { gain: 0.16, rate: 1.5, lp: 4500, cut: 0.03 });
  noise('bandpass', 3000, 1600, 0.04, 0.06, { attack: 0.004, q: 1.5 });
}
// 弾が管の奥へ入りきる: 蓋がばねで閉じる短い「パチッ」と、親指で押し込んだ鈍い「コッ」。
// 込めるほど管のばねが詰まって、少し高く鳴る（full: 0〜1）
export function playRifleLoad(full = 0) {
  const r = 1 + 0.12 * full;
  sample('metal_tick', { gain: 0.3, rate: 1.1 * r, lp: 3500, cut: 0.035 });
  noise('bandpass', 2200 * r, 1400 * r, 0.08, 0.018, { attack: 0.001, q: 1.2 });
  sample('thud', { gain: 0.26, rate: 1.6 * r, lp: 1400, cut: 0.07, delay: 0.004 });
}
// 込め終えて構えへ戻す: 服の擦れと、銃床を肩へ収める鈍い音
export function playRifleShoulder() {
  sample('cloth', { gain: 0.2, rate: 1.2 });
  sample('thud', { gain: 0.16, rate: 1.1, lp: 800, delay: 0.1, cut: 0.1 });
}
// 弾が空のまま引き金を引いた
export function playDryFire() {
  sample('metal_tick', { gain: 0.35, rate: 1.4 });
}
// 倒してライフルの弾が増えた: 高く短い金属音を 2 つ重ねる
export function playRifleGain() {
  playRing(2.4, 0.35, 0.05);
  setTimeout(() => playRing(3.1, 0.3, 0.05), 40);
  sample('metal_small', { gain: 0.25, rate: 1.4 });
}

export function playGrip() {
  playRing(1.9, 0.5, 0.04);
  setTimeout(() => playRing(1.45, 0.7, 0.07), 25);
  sample('metal_small', { gain: 0.3, rate: 1.3 });
  sample('metal_tick', { gain: 0.18, rate: 1.4, delay: 0.025 });
}

// 斧を握り直したときの「ガチャッ」: 厚い鉄の頭と柄がぶつかる、低く鈍い金属音。
// 金属音は低く短くして高い帯域を落とし、握り込んだ手応えの鈍い打音を下に敷く
export function playAxeGrip() {
  playRing(0.75, 0.6, 0.05);
  setTimeout(() => playRing(0.55, 0.8, 0.09), 30);
  sample('metal_small', { gain: 0.4, rate: 0.6, lp: 3500 });
  sample('metal_tick', { gain: 0.22, rate: 0.7, lp: 3000, delay: 0.03 });
  sample('thud_heavy', { gain: 0.35, rate: 0.9, lp: 900 });
}

// バットを構えに収めて握り直したときの「ガチッ」: 中が空の金属の胴が短く鳴る「キン」を、握り込んだ鈍い打音に重ねる
export function playBatGrip() {
  playRing(1.05, 0.45, 0.16);
  sample('metal_tick', { gain: 0.3, rate: 0.8, lp: 4000 });
  sample('thud_heavy', { gain: 0.25, rate: 1.1, lp: 1200, delay: 0.01 });
}

// 武器を持ち替えた: 武器ごとに抜く音を変える
export function playEquip(weapon: 'kunai' | 'handgun' | 'sword' | 'sickle' | 'axe' | 'bow' | 'bat' | 'spear' | 'rifle') {
  sample('gear', { gain: 0.35 });
  sample('cloth', { gain: 0.2, rate: 1.2 });
  if (weapon === 'kunai') {
    sample('knife_draw', { gain: 0.9, rate: 1.1, delay: 0.02 }); // 握り込む音は取り出しの最後に鳴らす（kunaiCombat.ts）
  } else if (weapon === 'handgun') {
    sample('gun_latch', { gain: 0.45, rate: 1.1, delay: 0.03 });
    sample('metal_tick', { gain: 0.3, rate: 0.9, delay: 0.09 });
  } else if (weapon === 'rifle') {
    sample('gun_latch', { gain: 0.5, rate: 0.8, delay: 0.03 }); // レバーを起こして戻す
    sample('metal_tick', { gain: 0.35, rate: 0.7, delay: 0.12 });
  } else if (weapon === 'bat' || weapon === 'spear') {
    sample('metal_tick', { gain: 0.25, rate: 0.6, lp: 3000, delay: 0.04 }); // バットと槍は鞘から抜かないので、握り直す小さな音だけ
  } else if (weapon !== 'bow') { // 弓は金物の音を鳴らさない
    // 斧は重いので低く遅く
    sample('unsheathe', { gain: 0.55, rate: weapon === 'sickle' ? 1.2 : weapon === 'axe' ? 0.8 : 1, delay: 0.02, reverb: 0.15 });
    playRing(weapon === 'sickle' ? 1.6 : weapon === 'axe' ? 0.8 : 1.2, 0.4, 0.4);
    if (weapon === 'sickle') playChain('ready');
  }
}

// 鎖鎌の鎖の「ジャラッ」。録音の鎖の音を、場面ごとに速さ・長さ・重ね方を変えて鳴らす。
// 両手の鎖が同じ瞬間に同じ音を出すことが多いので、同じ場面の音は続けて鳴らさない
export type ChainCue = 'ready' | 'windup' | 'throw' | 'taut' | 'pull' | 'reel';
const lastChain: Partial<Record<ChainCue, number>> = {};
export function playChain(cue: ChainCue) {
  if (!ctx) return;
  const now = ctx.currentTime;
  if (now - (lastChain[cue] ?? -1) < 0.06) return;
  lastChain[cue] = now;
  switch (cue) {
    case 'ready': // 構えて鎖が揺れる、小さく軽い音
      sample('chain', { gain: 0.25, rate: 1.25, hp: 1200, cut: 0.18 });
      break;
    case 'windup': // 回し始めに鎖がほどける
      sample('chain', { gain: 0.35, rate: 1.1, hp: 1000, cut: 0.25 });
      break;
    case 'throw': // 放った鎖が手元から勢いよく繰り出されていく「ジャラララッ」
      sample('chain', { gain: 0.55, rate: 1.35, hp: 800, reverb: 0.08 });
      sample('chain', { gain: 0.35, rate: 1.15, hp: 800, delay: 0.07, cut: 0.35 });
      sample('metal_tick', { gain: 0.12, rate: 1.6, delay: 0.03 });
      break;
    case 'taut': // 刺さって鎖がビンと張る「ジャキッ」
      sample('chain', { gain: 0.5, rate: 0.95, hp: 600, cut: 0.16 });
      break;
    case 'pull': // 張った鎖をたぐって一気に引き寄せる、重めで長い音
      sample('chain', { gain: 0.6, rate: 0.85, hp: 400, reverb: 0.12 });
      sample('chain', { gain: 0.4, rate: 1.05, hp: 700, delay: 0.06, cut: 0.4 });
      break;
    case 'reel': // 鎖を巻き戻す
      sample('chain', { gain: 0.4, rate: 1.3, hp: 900, cut: 0.3 });
      break;
  }
}

// 投げたクナイが壁や地面に刺さった「カッ」
export function playStick() {
  sample('wood', { gain: 0.6, rate: 1.1 });
  sample('metal_small', { gain: 0.22, rate: 0.8 });
  playRing(0.6, 0.5, 0.15);
}

// クナイを投げる: 腕の振りの風切りに、袖のはためきを添える
export function playThrow(s: SwishParams, kind: SwishKind = 'kunai') {
  playSwish(s, kind);
  sample('cloth', { gain: 0.18, rate: 1.4 });
}

// 投げる溜めを始めた・1 段溜まった
export function playCharge(stage: number) {
  if (stage === 0) {
    playRing(0.8, 0.6, 0.2);
    sample('metal_small', { gain: 0.25, rate: 0.9 });
  } else {
    playRing(0.8 + 0.25 * stage, 1.4, 0.3);
    sample('glass', { gain: 0.12 + 0.05 * stage, rate: 0.9 + 0.15 * stage });
  }
}

// ---- 弓 ----
// 録音の弓（ロングボウの引き・射ち・つがえ、クロスボウの射ち、重い矢の風切り）を、乾いて低い方へ寄せて重ねる

// 弦を引き始めた: 弓がしなる「ギィ…」を、離すかやめるまで鳴らす。返した関数を呼ぶと素早く絞って止める
export function playBowDraw(): () => void {
  if (!ctx) return () => {};
  sample('cloth', { gain: 0.16, rate: 0.9 });
  sample('bow_nock', { gain: 0.14, rate: 0.8, lp: 3000 }); // 指が弦に掛かる小さな「カッ」
  const buf = pick('bow_draw');
  if (!buf) return () => {};
  const c = ctx;
  const t0 = c.currentTime;
  const src = c.createBufferSource();
  src.buffer = buf;
  src.playbackRate.value = 0.85 * rand(0.96, 1.04) * (1 - 0.35 * slowAmt);
  const g = c.createGain();
  // 引き始めは小さく、引くほど張りつめて大きくなる
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(0.18, t0 + 0.12);
  g.gain.linearRampToValueAtTime(0.42, t0 + 0.9);
  src.connect(filter('highpass', 180)).connect(filter('lowpass', 4200)).connect(g).connect(bus);
  src.start(t0);
  src.stop(t0 + buf.duration / src.playbackRate.value + 0.05);
  return () => {
    const t = c.currentTime;
    g.gain.cancelScheduledValues(t);
    g.gain.setValueAtTime(g.gain.value, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.05);
    src.stop(t + 0.06);
  };
}

// 射った: 弦が戻る「ビン」と、弓の胴が受ける鈍い「ドッ」、矢が離れていく風切りを重ねる。
// 深く引くほど重く速い
export function playBowRelease(draw: number) {
  if (!ctx) return;
  sample('bow_shoot', { gain: 0.35 + 0.45 * draw, rate: 1.05 - 0.15 * draw, lp: 6000 });
  sample('bow_thump', { gain: 0.25 + 0.45 * draw, rate: 0.8 - 0.1 * draw, lp: 2200 });
  sample('arrow_pass', { gain: 0.15 + 0.35 * draw, rate: 0.9 + 0.35 * draw, hp: 300, delay: 0.015, cut: 0.25 + 0.2 * draw });
  tone(140 - 40 * draw, 45, 0.25 + 0.3 * draw, 0.12 + 0.08 * draw, { attack: 0.003 });
}

// 矢が敵に刺さった: 当たりの音（playHit）に重ねる、肉に深く入る鈍い「ドスッ」
export function playArrowHit() {
  if (!ctx) return;
  sample('wood', { gain: 0.35, rate: 0.7, lp: 2500 });
  sample('bow_thump', { gain: 0.3, rate: 0.6, lp: 1200 });
}

// 矢が壁や床に刺さった: 乾いた「トッ」と、刺さった矢柄が震える短い「ビィン」
export function playArrowStick() {
  if (!ctx) return;
  sample('wood', { gain: 0.5, rate: 0.95 });
  sample('plank', { gain: 0.18, rate: 1.1, lp: 3500, cut: 0.15 });
  const t0 = ctx.currentTime;
  for (const f of [182, 189]) { // わずかにずらした 2 本で、震えのうなりを作る
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(f * (1 - 0.35 * slowAmt), t0);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(0.05, t0 + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.28);
    osc.connect(g).connect(bus);
    osc.start(t0);
    osc.stop(t0 + 0.3);
  }
}

// 矢が壁や床で跳ねた: 硬い面を鏃がかすめる短く乾いた「カッ」と、跳ねていく風切り
export function playArrowRicochet() {
  if (!ctx) return;
  sample('wood', { gain: 0.3, rate: 1.4, lp: 4000, cut: 0.08 });
  noise('bandpass', rand(3000, 3800), 1400, 0.12, 0.04, { q: 1.2, attack: 0.001 });
  noise('bandpass', 1800, 700, 0.05, 0.16, { q: 0.8, attack: 0.01, delay: 0.015 });
}

// 次の矢をつがえた: 矢筈が弦に掛かる「カチッ」と、矢を抜く小さな擦れ
export function playBowNock() {
  if (!ctx) return;
  sample('bow_nock', { gain: 0.45, rate: 0.95, lp: 6000 });
  sample('cloth', { gain: 0.1, rate: 1.3, cut: 0.15 });
}

// 取り出しで回した弓を握り込んだ: 木の柄を掌で受ける乾いた「パシッ」と、揺れる弦の低い唸り
export function playBowCatch() {
  if (!ctx) return;
  sample('wood', { gain: 0.4, rate: 1.3, lp: 5000 });
  sample('punch', { gain: 0.15, rate: 1.4, lp: 2500 });
  sample('bow_thump', { gain: 0.18, rate: 0.7, lp: 1500, delay: 0.01 });
}

// 居合の構え: 鯉口を切る「チャッ」と、空気を吸い込むような逆再生のうねり
export function playFocusStart() {
  playGrip();
  playSwish({ dur: 0.3, f0: 250, f1: 700, gain: 0.2 }, 'sword');
  sample('focus', { gain: 0.5, rate: 0.55, reversed: true, lp: 3000, reverb: 0.4 });
  sample('knife_draw', { gain: 0.5, rate: 0.75 });
}

// 投げたクナイで世界だけが遅くなる: 入った瞬間に低く沈み込む「ヴゥン」、明けるときに吸い戻す逆再生の「シュッ」。
// どちらもこもりを通さない parryBus へ出して、こもった世界の音の上にはっきり乗せる
export function playWorldSlow(hold: number, release: number) {
  if (!ctx) return;
  const out = parryBus;
  const dry = { out, pan: 0, jitter: 0.02 };
  tone(150, 38, 0.55, 0.45, { attack: 0.005, out });
  sample('thud_heavy', { ...dry, gain: 0.4, rate: 0.55, lp: 600 });
  sample('focus', { ...dry, gain: 0.35, rate: 0.45, lp: 1800, reverb: 0.3 });
  noise('lowpass', 1400, 120, 0.18, 0.4, { attack: 0.004, out });
  // 明ける: 戻り始めから戻りきる所へ向けて吸い込み、戻りきった所で短く切る
  sample('swish', { ...dry, gain: 0.35, rate: 0.7, reversed: true, lp: 4000, delay: hold - 0.1, cut: release + 0.1 });
  tone(60, 160, 0.2, release + 0.1, { attack: release, out, delay: hold - 0.1 });
}

// ロックオンした瞬間の「キン」: 合成の金属音に、鐘とガラスの余韻を重ねる
export function playLockOn() {
  playRing(1.6, 0.9, 0.25);
  sample('bell', { gain: 0.16, rate: 1.6, reverb: 0.5 });
  sample('glass', { gain: 0.18, rate: 1.2, reverb: 0.3 });
}

// デッドアイに入る: 撃鉄を起こす「カチリ」と、低く沈み込む「ヴゥン」
export function playDeadEyeStart() {
  if (!ctx) return;
  sample('gun_latch', { gain: 0.5, rate: 0.8 });
  sample('metal_tick', { gain: 0.35, rate: 0.7, delay: 0.05 });
  playRing(0.7, 0.5, 0.05);
  tone(140, 40, 0.4, 0.45, { attack: 0.005 });
  sample('focus', { gain: 0.35, rate: 0.5, reversed: true, lp: 2200, reverb: 0.3 });
}

// 印を付けた: 小さく乾いた「チッ」。付けるたびに少しずつ高くする
export function playDeadEyeMark(count: number) {
  if (!ctx) return;
  const k = 1 + (count - 1) * 0.08;
  playRing(1.4 * k, 0.45, 0.05);
  sample('metal_tick', { gain: 0.25, rate: 1.2 * k });
}

// 撃ち始める: 指を掛け直す短い握りの音
export function playDeadEyeFire() {
  playGrip();
}

// 居合の突進: 地を蹴る重い踏み込みと、大きく空気を裂く音
export function playRush() {
  playSwish({ dur: 0.3, f0: 200, f1: 1100, gain: 0.6 }, 'sword');
  sample('step_hard', { gain: 0.8, rate: 0.7 });
  sample('thud_heavy', { gain: 0.6, rate: 0.9 });
  sample('swish', { gain: 0.6, rate: 0.5, reversed: true });
  noise('bandpass', 300, 2600, 0.35, 0.35, { attack: 0.12, q: 0.6 });
  tone(90, 40, 0.4, 0.3);
}

// ---- ストライカー ----
// 振りかぶり: 刃を返す短い金属の「チャキッ」に、高く細い「キィ」を重ねる。背後からでも斬られる前に気づけるよう、銃声より目立たせる。
// volume と pan は敵の距離と向きから決める
export function playStrikerWindup(volume = 1, pan = 0) {
  if (!ctx) return;
  sample('knife_draw', { gain: 0.6 * volume, rate: 1.1, hp: 900, pan });
  sample('metal_small', { gain: 0.35 * volume, rate: 1.3, pan, delay: 0.02 });
  noise('bandpass', 5000, 9000, 0.08 * volume, 0.25, { q: 4, attack: 0.08, reverb: 0.15 });
}

// 斬撃: 薄い刃が空気を裂く短い風切り
export function playStrikerSlash(volume = 1) {
  playSwish({ dur: 0.2, f0: 400, f1: 2400, gain: 0.45 * volume }, 'sickle');
}

// 飛び降りて着地した: 金属の脚が床を打つ重い「ドスッ」。高い所から降りるほど低く重くする（impact は着く速さ m/s）
export function playStrikerLand(impact: number, volume = 1, pan = 0) {
  if (!ctx) return;
  const k = Math.min(1, impact / 15);
  sample('step_hard', { gain: (0.4 + 0.4 * k) * volume, rate: 0.75, pan });
  sample('thud_heavy', { gain: (0.3 + 0.5 * k) * volume, rate: 0.9 - 0.2 * k, lp: 900, pan, reverb: 0.2 });
  sample('metal_small', { gain: 0.2 * volume, rate: 0.7, pan, delay: 0.02 });
}

// 斬られた: 刃が入る「ザッ」。高い音は短く切り、体に響く鈍い音は playHurt に任せる
export function playStrikerCut() {
  sample('slice', { gain: 0.7, rate: 0.85, lp: 5000 });
  noise('highpass', 3000, 1500, 0.2, 0.06, { attack: 0.002 });
}

// ---- 狙撃手 ----
// 狙い始め: ボルトを引く金属の「ガチャッ」。照準線が出る合図
export function playSniperAim(volume = 1, pan = 0) {
  if (!ctx) return;
  sample('gun_latch', { gain: 0.5 * volume, rate: 0.8, pan });
  sample('metal_small', { gain: 0.25 * volume, rate: 0.6, pan, delay: 0.06 });
}

// 照準が止まった: 短く高い 2 回の「ピピッ」。この後すぐに撃つので、聞こえたら動く
export function playSniperLock(volume = 1) {
  tone(2400, 2400, 0.1 * volume, 0.05);
  tone(2400, 2400, 0.1 * volume, 0.05, { delay: 0.08 });
}

// 撃った: 普通の銃声に、遠くまで響く低いうなりを重ねる
export function playSniperShot(volume = 1, pan = 0) {
  playGunshot(volume, pan);
  sample('thud_heavy', { gain: 0.6 * volume, rate: 0.5, lp: 500, pan, reverb: 0.5 });
}

// ---- ボス ----
// 大きな機体なので、どれも低く重く鳴らす。volume と pan は機体の距離と向きから決める

// 左右の位置を付けた出口（合成音を機体のいる向きから鳴らす）
function panOut(pan: number, out: AudioNode = bus) {
  const p = ctx!.createStereoPanner();
  p.pan.value = pan;
  p.connect(out);
  return p;
}


// ボスの音の作り方（聴き比べて決めたこと）:
// ・音の大きさは耳がよく聞く 150Hz〜5kHz で決まる。重さは素材をごく低く落とした層で出し、大きさは速度をあまり落とさない層で出す。
//   重さの層の 40Hz より下（BOSS_SUB_HP）は、ほぼ聞こえずに音量の上限だけを食うので削る
// ・音程が動くのこぎり波やサイン波の唸り、高い音域で長く続くノイズは、安っぽく（「プー」「砂嵐」に）聞こえるので使わない。
//   機械が動く音は歯車の素材、動力の高まりは低い所だけを通したノイズで作る
// ・大きな衝撃には爆発の素材を混ぜ、特に大きなものは広い所の響き（hall）へ送る
const BOSS_SUB_HP = 40;

// 足を着いた「ズゥン」: 鉄の足が床を打つ低い重さと、聞こえる高さの鈍い一打、関節の小さな軋み
export function playBossStep(volume = 1, pan = 0) {
  if (!ctx) return;
  sample('thud_heavy', { gain: 0.5 * volume, rate: 0.5, hp: BOSS_SUB_HP, lp: 450, pan, reverb: 0.15 });
  sample('thud_heavy', { gain: 0.3 * volume, rate: 0.8, lp: 2200, pan, cut: 0.25 });
  sample('step_hard', { gain: 0.35 * volume, rate: 0.6, lp: 2200, pan, cut: 0.15 });
  sample('metal_small', { gain: 0.08 * volume, rate: 0.5, lp: 2000, pan, delay: 0.03, cut: 0.2 });
}

// 機体の重い衝撃（跳ぶ・降りる・床を叩く・突進で激突する・柱をもぎ取る）。power は強さ（0.5〜6 ほど）。
// 強いほど低く重い層と爆発の層を足し、広い所に響かせる
export function playBossImpact(power = 1, pan = 0) {
  if (!ctx) return;
  const k = Math.min(power, 3) / 3; // 0〜1
  sample('thud_heavy', { gain: 0.3 + 0.5 * k, rate: 0.5, hp: BOSS_SUB_HP, lp: 900, pan, cut: 0.8 });
  sample('gun_sub', { gain: 0.2 + 0.4 * k, rate: 0.55, hp: BOSS_SUB_HP, pan, cut: 0.6 });
  sample('thud_heavy', { gain: 0.25 + 0.35 * k, rate: 0.8, lp: 2500, pan, cut: 0.35, hall: 0.3 * k });
  sample('step_hard', { gain: 0.3 + 0.2 * k, rate: 0.55, lp: 2000, pan, cut: 0.2 });
  sample('plate', { gain: 0.1 + 0.15 * k, rate: 0.5, lp: 1800, pan, cut: 0.3 });
  noise('lowpass', 700, 100, 0.15 + 0.15 * k, 0.3, { attack: 0.003, out: panOut(pan) });
  if (k > 0.35) {
    sample('explosion', { gain: 0.75 * k, rate: 0.75, lp: 3500, pan, cut: 0.9, hall: 0.6 * k });
    sample('punch_heavy', { gain: 0.5 * k, rate: 0.6, lp: 3000, pan, cut: 0.3 });
  }
}

// 噴射で一気に動く（突進・跳躍・横へ滑る・投げる）: 噴射口が火を噴く短く太い「ドシュッ」
export function playBossThrust(volume = 1, pan = 0) {
  if (!ctx) return;
  sample('punch_heavy', { gain: 0.45 * volume, rate: 0.6, lp: 2500, pan, cut: 0.3 });
  sample('thud_heavy', { gain: 0.35 * volume, rate: 0.7, lp: 1500, pan, cut: 0.3 });
  sample('swish', { gain: 0.45 * volume, rate: 0.45, lp: 2000, pan, reversed: true });
  noise('bandpass', 400, 1100, 0.22 * volume, 0.35, { attack: 0.01, q: 0.7, out: panOut(pan) });
}

// 油圧で脚や胴体を動かす: 構える瞬間の「ガチャ」と、だんだん速く回る歯車、低く膨らむ動力の音。
// 攻撃の合図でもあるので、背後からでも気づけるくらいの大きさにする
export function playBossServo(dur: number, volume = 1, pan = 0, pitch = 1) {
  if (!ctx) return;
  sample('gun_latch', { gain: 0.35 * volume, rate: 0.6 * pitch, lp: 2500, pan });
  const n = Math.max(1, Math.ceil(dur / 0.22));
  for (let i = 0; i < n; i++) {
    sample('gear', { gain: 0.24 * volume, rate: (0.5 + 0.2 * (i / n)) * pitch, lp: 1800, pan, cut: 0.3, delay: i * 0.22 * (1 - 0.15 * (i / n)) });
  }
  noise('lowpass', 250 * pitch, 650 * pitch, 0.12 * volume, dur, { attack: dur * 0.8, out: panOut(pan) });
}

// 蒸気を逃がす「プシュー」: 高すぎる所は削って、ざらつきを抑える
export function playBossHiss(dur: number, volume = 1, pan = 0, delay = 0) {
  if (!ctx) return;
  const out = panOut(pan);
  noise('bandpass', 2500, 1200, 0.045 * volume, dur, { attack: 0.03, q: 0.7, delay, out });
  noise('bandpass', 900, 500, 0.04 * volume, dur * 0.7, { attack: 0.02, q: 0.8, delay, out });
}

// ミサイルの発射口を開ける「ガコン」
export function playBossHatch(volume = 1, pan = 0) {
  sample('gun_latch', { gain: 0.45 * volume, rate: 0.55, lp: 1800, pan });
  sample('plate', { gain: 0.12 * volume, rate: 0.5, lp: 1200, pan, delay: 0.05, cut: 0.25 });
}

// ミサイルの打ち上げ「シュボッ」: 短い噴射の吹き出しと、筒から押し出す鈍い音
export function playMissileLaunch(volume = 1, pan = 0) {
  if (!ctx) return;
  const out = panOut(pan);
  noise('bandpass', 500, 2200, 0.2 * volume, 0.22, { attack: 0.01, q: 0.7, out });
  noise('lowpass', 700, 150, 0.18 * volume, 0.15, { attack: 0.002, out });
  sample('thud', { gain: 0.3 * volume, rate: 0.7, lp: 800, pan });
  sample('punch', { gain: 0.25 * volume, rate: 0.8, lp: 2500, pan, cut: 0.15 });
}

// ミサイルの爆発「ボゴッ」: 爆発の素材を少し低く落とし、空気を押しつぶす低い圧と鈍い一打を重ねる
export function playMissileBlast(volume = 1) {
  if (!ctx) return;
  sample('explosion', { gain: 0.7 * volume, rate: 0.85, lp: 3500, cut: 0.7, hall: 0.25 });
  sample('thud_heavy', { gain: 0.4 * volume, rate: 0.8, lp: 2000, cut: 0.3 });
  sample('thud_heavy', { gain: 0.6 * volume, rate: 0.6, hp: BOSS_SUB_HP, lp: 700 });
  sample('gun_sub', { gain: 0.4 * volume, rate: 1.0, hp: BOSS_SUB_HP });
  noise('lowpass', 900, 90, 0.3 * volume, 0.3, { attack: 0.002 });
}

// 背中・かかとの噴射の音（鳴り続ける）。level は噴射の強さ（0 で止める）。毎フレーム呼ぶ
let jetGain: GainNode | null = null;
let jetFilter: BiquadFilterNode;
let jetPan: StereoPannerNode;
export function setBossJet(level: number, volume = 1, pan = 0) {
  if (!ctx) return;
  if (!jetGain) {
    if (level <= 0.01) return;
    // 低い「ゴォォ」: 低い所だけを通したノイズ（ざらつく中域は足さない）
    jetFilter = filter('lowpass', 300, 0.9);
    jetGain = ctx.createGain();
    jetGain.gain.value = 0;
    jetPan = ctx.createStereoPanner();
    const src = loopNoise(ctx);
    src.connect(jetFilter).connect(jetGain);
    jetGain.connect(jetPan).connect(bus);
  }
  const t = ctx.currentTime;
  const k = Math.min(level, 1.2);
  jetGain.gain.setTargetAtTime(0.4 * k * volume * rand(0.9, 1.1), t, 0.04);
  jetFilter.frequency.setTargetAtTime(200 + 450 * k, t, 0.05);
  jetPan.pan.setTargetAtTime(pan, t, 0.05);
}

// 装甲に弾かれた「コッ」: 部位が残っていて本体に通らない・故障済みの部位に当てた。
// 何も起きていないことが分かるよう、小さく乾いた音だけ。連射で鳴りすぎないよう間を空ける
let lastArmor = 0;
export function playBossArmor() {
  if (!ctx || ctx.currentTime - lastArmor < 0.09) return;
  lastArmor = ctx.currentTime;
  sample('metal_tick', { gain: 0.14, rate: 0.55, lp: 1800 });
  sample('plate', { gain: 0.06, rate: 0.7, lp: 1500, cut: 0.08 });
}

// 部位や本体に通った: いつもの当たりの音に重ねる、厚い鉄板の鈍い「ガン」
export function playBossPlate(power = 1) {
  sample('plate', { gain: 0.16 * Math.min(power, 2), rate: 0.45, lp: 1600, cut: 0.25 });
}

// 部位が故障した: 装甲の中で弾ける「バゴッ」と、鉄がねじ切れる「ガギャッ」、飛び散った装甲が床で鳴る音
export function playBossBreak(volume = 1, pan = 0) {
  if (!ctx) return;
  sample('explosion', { gain: 0.45 * volume, rate: 1.0, lp: 3500, pan, cut: 0.5, hall: 0.3 });
  sample('punch_heavy', { gain: 0.5 * volume, rate: 0.7, lp: 3000, pan, cut: 0.3 });
  sample('plate', { gain: 0.4 * volume, rate: 0.45, lp: 2500, pan, cut: 0.45 });
  sample('clash', { gain: 0.22 * volume, rate: 0.55, lp: 3000, pan, delay: 0.02, cut: 0.3 });
  for (let i = 0; i < 3; i++) sample('metal_small', { gain: 0.1 * volume, rate: rand(0.55, 0.7), lp: 2500, pan, cut: 0.15, delay: 0.3 + i * rand(0.1, 0.18) });
  playBossHiss(0.5, 0.7 * volume, pan, 0.1);
}

// 4 つとも故障してしゃがみ込んだ: 歯車が止まっていき、動力が落ちる低い音と、膝を着く重い「ドズン」
export function playBossPowerDown(volume = 1, pan = 0) {
  if (!ctx) return;
  sample('gear', { gain: 0.3 * volume, rate: 0.45, lp: 1500, pan, cut: 0.5 });
  sample('gear', { gain: 0.22 * volume, rate: 0.35, lp: 1200, pan, cut: 0.5, delay: 0.18 });
  noise('lowpass', 500, 80, 0.2 * volume, 1.0, { attack: 0.02, out: panOut(pan) });
  sample('thud_heavy', { gain: 0.8 * volume, rate: 0.45, hp: BOSS_SUB_HP, lp: 500, pan, delay: 0.35 });
  sample('thud_heavy', { gain: 0.5 * volume, rate: 0.7, lp: 2000, pan, delay: 0.35, cut: 0.4, hall: 0.4 });
  sample('plate', { gain: 0.25 * volume, rate: 0.4, lp: 1500, pan, delay: 0.37, cut: 0.5, hall: 0.3 });
  playBossHiss(1.4, volume, pan, 0.45);
}

// 部位を直して起き上がる: 歯車が回り始め、動力が高まって、立ちきったときの「ガシャン」
export function playBossPowerUp(dur: number, volume = 1, pan = 0) {
  if (!ctx) return;
  sample('gear', { gain: 0.3 * volume, rate: 0.45, lp: 1500, pan, cut: dur });
  sample('gear', { gain: 0.22 * volume, rate: 0.6, lp: 1800, pan, cut: dur * 0.5, delay: dur * 0.5 });
  noise('lowpass', 120, 700, 0.15 * volume, dur, { attack: dur * 0.8, out: panOut(pan) });
  sample('gun_latch', { gain: 0.55 * volume, rate: 0.55, lp: 2000, pan, delay: dur });
  sample('thud_heavy', { gain: 0.5 * volume, rate: 0.6, lp: 2000, pan, delay: dur, cut: 0.4 });
  sample('plate', { gain: 0.2 * volume, rate: 0.5, lp: 1800, pan, delay: dur + 0.01, cut: 0.3 });
}

// 必殺技の溜め: 震えながら高まっていく動力の轟き（dur 秒で頂点）。音程のある唸りではなく、
// 低い所だけを通したノイズを、震わせながら少しずつ明るくする。歯車の音もだんだん詰まっていく
export function playBossUltCharge(dur: number, volume = 1, pan = 0) {
  if (!ctx) return;
  const t0 = ctx.currentTime;
  const out = panOut(pan);
  const trem = ctx.createGain();
  trem.gain.value = 0.7;
  const lfo = ctx.createOscillator();
  lfo.frequency.setValueAtTime(8, t0);
  lfo.frequency.exponentialRampToValueAtTime(30, t0 + dur);
  const depth = ctx.createGain();
  depth.gain.value = 0.3;
  lfo.connect(depth).connect(trem.gain);
  trem.connect(out);
  lfo.start(t0);
  lfo.stop(t0 + dur + 0.05);
  noise('lowpass', 90, 1200, 0.4 * volume, dur, { attack: dur * 0.95, out: trem });
  noise('lowpass', 60, 300, 0.25 * volume, dur, { attack: dur * 0.9, out: trem });
  for (let at = 0, gap = 0.3; at < dur; at += gap, gap = Math.max(0.06, gap * 0.8)) {
    sample('gear', { gain: (0.12 + 0.2 * (at / dur)) * volume, rate: 0.5 + 0.3 * (at / dur), lp: 2000, pan, cut: 0.2, delay: at });
  }
}

// 止まった: 砕ける一打（playFinale）が明けてから、機体が崩れ落ちる。世界の音が消えている間も聞こえるよう parryBus へ出す
export function playBossCollapse(delay: number, volume = 1, pan = 0) {
  if (!ctx) return;
  const out = panOut(pan, parryBus);
  const dry = { out: parryBus, pan, jitter: 0.03 };
  sample('gear', { ...dry, gain: 0.25 * volume, rate: 0.4, lp: 1200, cut: 0.6, delay });
  noise('lowpass', 400, 60, 0.2 * volume, 1.4, { attack: 0.02, delay, out });
  sample('thud_heavy', { ...dry, gain: 0.75 * volume, rate: 0.42, hp: BOSS_SUB_HP, lp: 450, delay: delay + 0.3 });
  sample('thud_heavy', { ...dry, gain: 0.5 * volume, rate: 0.65, lp: 2000, cut: 0.4, delay: delay + 0.3 });
  sample('plate', { ...dry, gain: 0.25 * volume, rate: 0.38, lp: 1500, delay: delay + 0.32, cut: 0.5 });
  sample('thud_heavy', { ...dry, gain: 0.45 * volume, rate: 0.55, lp: 1200, cut: 0.4, delay: delay + 0.62 });
}
// 止まった後、爆発するまでの小さな破裂: 装甲の中で弾ける短い「ボッ」と、こもった「ドッ」。尾は残さない。
// 世界の音が戻る前から鳴るので parryBus へ出す
export function playBossPop(volume = 1, pan = 0) {
  if (!ctx) return;
  const dry = { out: parryBus, pan, jitter: 0.05 };
  sample('explosion', { ...dry, gain: 0.3 * volume, rate: rand(1.0, 1.2), lp: 3000, cut: 0.25 });
  sample('thud_heavy', { ...dry, gain: 0.45 * volume, rate: rand(0.62, 0.75), lp: 650, cut: 0.16 });
  sample('plate', { ...dry, gain: 0.1 * volume, rate: rand(0.5, 0.6), lp: 1400, cut: 0.08 });
}
// 爆発: 壁を突き破ったときと同じ作りの、重く大きな一撃。爆発の素材を低く落として重ね、一拍遅れて二段目を落とし、
// 広い所に響かせる。世界の音が戻る前でも聞こえるよう、全体のコンプレッサーを通さない出口（boomBus）へ出す
export function playBossExplode(volume = 1, pan = 0) {
  if (!ctx) return;
  const v = volume * 1.5;
  const dry = { out: boomBus, pan, jitter: 0.02 };
  // 重さの層
  sample('thud_heavy', { ...dry, gain: 0.9 * v, rate: 0.35, hp: BOSS_SUB_HP, lp: 900, cut: 0.9 });
  sample('gun_sub', { ...dry, gain: 0.7 * v, rate: 0.45, hp: BOSS_SUB_HP, cut: 0.8 });
  // 大きさの層: 爆発と打撃
  sample('explosion', { ...dry, gain: 0.9 * v, rate: 0.65, lp: 4000, cut: 1.2, hall: 0.9 });
  sample('explosion', { ...dry, gain: 0.6 * v, rate: 0.45, lp: 2200, cut: 1.3, delay: 0.02, hall: 0.6 });
  sample('punch_heavy', { ...dry, gain: 0.8 * v, rate: 0.6, lp: 4000, cut: 0.35, hall: 0.5 });
  sample('plate', { ...dry, gain: 0.45 * v, rate: 0.42, lp: 2000, cut: 1.0, hall: 0.8 });
  // 二段目: 一拍遅れて、さらに低く沈む
  sample('thud_heavy', { ...dry, gain: 0.6 * v, rate: 0.45, lp: 1800, cut: 0.8, delay: 0.12, hall: 0.6 });
  sample('thud_heavy', { ...dry, gain: 0.6 * v, rate: 0.3, hp: BOSS_SUB_HP, lp: 500, cut: 0.9, delay: 0.12 });
  noise('lowpass', 450, 60, 0.35 * v, 1.4, { attack: 0.01, out: boomBus });
}

